    RetireInput,
    Validate,
    Publish,
    Terminal,
}

impl DatabaseCatalogBootstrapPhase {
    fn from_u8(value: u8) -> Self {
        match value {
            0 => Self::Handoff,
            1 => Self::Poll,
            2 => Self::RetainWork,
            3 => Self::CloseWork,
            4 => Self::RetireInput,
            5 => Self::Validate,
            6 => Self::Publish,
