            document: Mutex::new(Some(document)),
            cursor: Mutex::new(DatabaseCreateCatalogCursor {
                base: Some(base),
                backing,
                base_epoch,
                base_revision,
                base_identity,
                created_at_ms,
                encoded_len: 2,
                scan_entry: 0,
                scan_byte: 0,
                scan_started: false,
                candidate: None,
                clone_entry: 0,
                clone_byte: 0,
                clone_text: None,
                snapshot: None,
                encode: DatabaseCreateCatalogEncodeCursor::new(),
                writer: None,
