    policy: DatabaseDocumentMountPolicy,
    create_claim: bool,
    reply: db_actor::ReplySender<Result<DatabaseDocumentMountReply, DbError>>,
}

struct DatabaseDocumentMountWait {
    receiver: db_actor::ReplyReceiver<Result<DatabaseDocumentMountReply, DbError>>,
    registry: std::sync::Weak<Mutex<DatabaseDocumentMountRegistry>>,
    document: String,
    generation: u64,
    slot: usize,
    resolved: bool,
}

impl Future for DatabaseDocumentMountWait {
    type Output = Result<Result<DatabaseDocumentMountReply, DbError>, DbError>;

    fn poll(self: std::pin::Pin<&mut Self>, context: &mut std::task::Context<'_>) -> std::task::Poll<Self::Output> {
        let this = self.get_mut();
        match std::pin::Pin::new(&mut this.receiver).poll(context) {
            std::task::Poll::Ready(result) => {
                this.resolved = true;
                std::task::Poll::Ready(result)
            }
            std::task::Poll::Pending => std::task::Poll::Pending,
        }
    }
}

impl Drop for DatabaseDocumentMountWait {
    fn drop(&mut self) {
        if self.resolved {
            return;
        }
        let Some(registry) = self.registry.upgrade() else { return };
        let mut registry = registry.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let Some(DatabaseDocumentMountSlot::Opening { generation, waiters, .. }) = registry.slots.get_mut(&self.document) else { return };
        if *generation == self.generation {
            waiters.get_mut(self.slot).and_then(Option::take);
        }
    }
}

enum DatabaseDocumentMountFailure {
    Terminal(DbError),
    Retained { rejected: db_artifact::ArtifactEngineOpenRejected, resume: Option<DatabaseDocumentMountFuture> },
}

impl From<DbError> for DatabaseDocumentMountFailure {
    fn from(error: DbError) -> Self {
        Self::Terminal(error)
    }
}

type DatabaseDocumentMountFuture = std::pin::Pin<Box<dyn Future<Output = Result<DatabaseDocumentMountReply, DatabaseDocumentMountFailure>> + Send + 'static>>;
type DatabaseDocumentMountCleanupFuture = std::pin::Pin<Box<dyn Future<Output = Result<DbError, db_artifact::ArtifactEngineOpenRejected>> + Send + 'static>>;

enum DatabaseDocumentMountWork {
    Mount(DatabaseDocumentMountFuture),
    Cleanup { future: DatabaseDocumentMountCleanupFuture, resume: Option<DatabaseDocumentMountFuture> },
    Parked { rejected: db_artifact::ArtifactEngineOpenRejected, resume: Option<DatabaseDocumentMountFuture> },
    Empty,
}

enum DatabaseDocumentMountPoll {
    Pending,
    Continue,
    Complete(Result<DatabaseDocumentMountReply, DbError>),
}

enum DatabaseDocumentMountSlot {
    Opening { generation: u64, owner: Arc<DatabaseDocumentMountOwner>, waiters: [Option<DatabaseDocumentMountWaiter>; DATABASE_DOCUMENT_MOUNT_WAITERS] },
    Ready(DatabaseDocumentMountReply),
    Closing { terminal: db_actor::ReplyReceiver<()> },
}

struct DatabaseDocumentMountRegistry {
    slots: HashMap<String, DatabaseDocumentMountSlot>,
    next_generation: u64,
}

impl DatabaseDocumentMountRegistry {
    fn new() -> Self {
        Self { slots: HashMap::new(), next_generation: 1 }
    }

    fn take_generation(&mut self) -> Result<u64, DbError> {
        let generation = self.next_generation;
        self.next_generation = generation.checked_add(1).filter(|next| *next != 0).ok_or(DbError::LimitExceeded("database document-mount generation"))?;
        Ok(generation)
    }

    fn ready_count(&self) -> usize {
        self.slots.values().filter(|slot| matches!(slot, DatabaseDocumentMountSlot::Ready(_))).count()
    }

    fn len(&self) -> usize {
        self.slots.len()
    }

    fn is_empty(&self) -> bool {
        self.slots.is_empty()
    }
}

#[repr(u8)]
#[derive(Clone, Copy, Eq, PartialEq)]
enum DatabaseDocumentMountDriver {
    Idle,
    Queued,
    Polling,
    NonRunnable,
    Terminal,
}

struct DatabaseDocumentMountOwner {
    pool: Arc<WorkerPool>,
    registry: std::sync::Weak<Mutex<DatabaseDocumentMountRegistry>>,
    document: String,
    generation: u64,
    work: Mutex<DatabaseDocumentMountWork>,
    retry_job: Mutex<Option<semio_framework_async::Job>>,
    scheduler_fault: Mutex<Option<semio_framework_async::WorkerSubmitErrorKind>>,
    retry_armed: std::sync::atomic::AtomicBool,
    driver: std::sync::atomic::AtomicU8,
    wake_requested: std::sync::atomic::AtomicBool,
    resume_requested: std::sync::atomic::AtomicBool,
    #[cfg(test)]
    cleanup_fault_hook: Arc<Mutex<Option<DatabaseDocumentMountCleanupFaultHook>>>,
    #[cfg(test)]
    parked_hook: Arc<Mutex<Option<DatabaseDocumentMountParkedHook>>>,
    terminal: std::sync::atomic::AtomicBool,
}

static DATABASE_DOCUMENT_MOUNT_WORK_LIVE: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// 🔬️ How many document-mount owners are still alive holding their boxed mount work. Each one
/// carries the `WorkerPoolUse` clone `mount_document` handed its `run_document_mount` future, and a
/// retained-open retry carries a SECOND clone in its `resume` future — and neither is in any slot
/// table, so a mount owner that outlives its registry entry pins the database's pool use invisibly.
fn database_document_mount_work_live_slots() -> usize {
    DATABASE_DOCUMENT_MOUNT_WORK_LIVE.load(std::sync::atomic::Ordering::Acquire)
}

impl Drop for DatabaseDocumentMountOwner {
    fn drop(&mut self) {
        DATABASE_DOCUMENT_MOUNT_WORK_LIVE.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
    }
}

struct DatabaseDocumentMountWake {
    owner: std::sync::Weak<DatabaseDocumentMountOwner>,
    generation: u64,
}

impl std::task::Wake for DatabaseDocumentMountWake {
    fn wake(self: Arc<Self>) {
        self.wake_by_ref();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        if let Some(owner) = self.owner.upgrade() {
            if owner.generation == self.generation {
                owner.request_drive(false);
            }
        }
    }
}

impl DatabaseDocumentMountOwner {
    fn new(
        pool: Arc<WorkerPool>,
        registry: std::sync::Weak<Mutex<DatabaseDocumentMountRegistry>>,
        document: String,
        generation: u64,
        future: DatabaseDocumentMountFuture,
        #[cfg(test)] cleanup_fault_hook: Arc<Mutex<Option<DatabaseDocumentMountCleanupFaultHook>>>,
        #[cfg(test)] parked_hook: Arc<Mutex<Option<DatabaseDocumentMountParkedHook>>>,
    ) -> Arc<Self> {
        DATABASE_DOCUMENT_MOUNT_WORK_LIVE.fetch_add(1, std::sync::atomic::Ordering::AcqRel);
        Arc::new(Self {
            pool,
            registry,
            document,
            generation,
            work: Mutex::new(DatabaseDocumentMountWork::Mount(future)),
            retry_job: Mutex::new(None),
            scheduler_fault: Mutex::new(None),
            retry_armed: std::sync::atomic::AtomicBool::new(false),
            driver: std::sync::atomic::AtomicU8::new(DatabaseDocumentMountDriver::Idle as u8),
            wake_requested: std::sync::atomic::AtomicBool::new(false),
            resume_requested: std::sync::atomic::AtomicBool::new(false),
            #[cfg(test)]
            cleanup_fault_hook,
            #[cfg(test)]
            parked_hook,
            terminal: std::sync::atomic::AtomicBool::new(false),
        })
    }

    fn request_drive(self: &Arc<Self>, resume: bool) {
        use std::sync::atomic::Ordering;
        if self.terminal.load(Ordering::Acquire) || self.driver.load(Ordering::Acquire) == DatabaseDocumentMountDriver::NonRunnable as u8 {
            return;
        }
        if resume {
            self.resume_requested.store(true, Ordering::Release);
        }
        self.wake_requested.store(true, Ordering::Release);
        self.queue_if_idle();
    }

    fn drive(self: &Arc<Self>) {
        self.request_drive(true);
    }

    fn queue_if_idle(self: &Arc<Self>) {
        use std::sync::atomic::Ordering;
        if self.driver.compare_exchange(DatabaseDocumentMountDriver::Idle as u8, DatabaseDocumentMountDriver::Queued as u8, Ordering::AcqRel, Ordering::Acquire).is_err() {
            return;
        }
        let owner = Arc::downgrade(self);
        let generation = self.generation;
        self.submit_exact(Box::new(move || {
            let Some(owner) = owner.upgrade() else { return };
            if owner.generation == generation {
                owner.poll_once();
            }
        }));
    }

    fn resume_parked(work: &mut DatabaseDocumentMountWork) {
        let current = std::mem::replace(work, DatabaseDocumentMountWork::Empty);
        *work = match current {
            DatabaseDocumentMountWork::Parked { rejected, resume } => DatabaseDocumentMountWork::Cleanup { future: Box::pin(rejected.retry_close()), resume },
            current => current,
        };
    }

    fn submit_exact(self: &Arc<Self>, job: semio_framework_async::Job) {
        match self.pool.try_submit(Lane::UserVisible, job) {
            Ok(()) => {}
            Err(error) => match error.kind() {
                semio_framework_async::WorkerSubmitErrorKind::Contended | semio_framework_async::WorkerSubmitErrorKind::Saturated => {
                    *self.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(error.into_job());
                    self.arm_retry();
                }
                kind => {
                    *self.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(error.into_job());
                    *self.scheduler_fault.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(kind);
                    self.driver.store(DatabaseDocumentMountDriver::NonRunnable as u8, std::sync::atomic::Ordering::Release);
                }
            },
        }
    }

    fn scheduler_fault(&self) -> Option<semio_framework_async::WorkerSubmitErrorKind> {
        *self.scheduler_fault.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
    }

    fn arm_retry(self: &Arc<Self>) {
        use std::sync::atomic::Ordering;
        if self.retry_armed.compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire).is_err() {
            return;
        }
        let owner = Arc::downgrade(self);
        self.pool.callback_at(self.pool.now_ms().saturating_add(1), move || {
            let Some(owner) = owner.upgrade() else { return };
            owner.retry_armed.store(false, Ordering::Release);
            let job = owner.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
            if let Some(job) = job {
                owner.submit_exact(job);
            }
        });
    }

    fn poll_once(self: Arc<Self>) {
        use std::sync::atomic::Ordering;
        if self.driver.compare_exchange(DatabaseDocumentMountDriver::Queued as u8, DatabaseDocumentMountDriver::Polling as u8, Ordering::AcqRel, Ordering::Acquire).is_err() {
            return;
        }
        self.wake_requested.store(false, Ordering::Release);
        let waker = std::task::Waker::from(Arc::new(DatabaseDocumentMountWake { owner: Arc::downgrade(&self), generation: self.generation }));
        let mut context = std::task::Context::from_waker(&waker);
        loop {
            #[cfg(test)]
            let mut parked_hook = None;
            let outcome = {
                let mut work = self.work.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
                if matches!(&*work, DatabaseDocumentMountWork::Parked { .. }) && self.resume_requested.swap(false, Ordering::AcqRel) {
                    Self::resume_parked(&mut work);
                }
                match std::mem::replace(&mut *work, DatabaseDocumentMountWork::Empty) {
                    DatabaseDocumentMountWork::Mount(mut future) => match future.as_mut().poll(&mut context) {
                        std::task::Poll::Pending => {
                            *work = DatabaseDocumentMountWork::Mount(future);
                            DatabaseDocumentMountPoll::Pending
                        }
                        std::task::Poll::Ready(Ok(reply)) => DatabaseDocumentMountPoll::Complete(Ok(reply)),
                        std::task::Poll::Ready(Err(DatabaseDocumentMountFailure::Terminal(error))) => DatabaseDocumentMountPoll::Complete(Err(error)),
                        std::task::Poll::Ready(Err(DatabaseDocumentMountFailure::Retained { rejected, resume })) => {
                            *work = DatabaseDocumentMountWork::Cleanup { future: Box::pin(rejected.retry_close()), resume };
                            DatabaseDocumentMountPoll::Continue
                        }
                    },
                    DatabaseDocumentMountWork::Cleanup { mut future, resume } => match future.as_mut().poll(&mut context) {
                        std::task::Poll::Pending => {
                            *work = DatabaseDocumentMountWork::Cleanup { future, resume };
                            DatabaseDocumentMountPoll::Pending
                        }
                        std::task::Poll::Ready(Ok(error)) => match resume {
                            Some(future) => {
                                *work = DatabaseDocumentMountWork::Mount(future);
                                DatabaseDocumentMountPoll::Continue
                            }
                            None => DatabaseDocumentMountPoll::Complete(Err(error)),
                        },
                        std::task::Poll::Ready(Err(rejected)) => {
                            #[cfg(test)]
                            if let Some(hook) = self.cleanup_fault_hook.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
                                hook();
                            }
                            *work = DatabaseDocumentMountWork::Parked { rejected, resume };
                            #[cfg(test)]
                            {
                                parked_hook = self.parked_hook.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
                            }
                            DatabaseDocumentMountPoll::Pending
                        }
                    },
                    parked @ DatabaseDocumentMountWork::Parked { .. } => {
                        *work = parked;
                        DatabaseDocumentMountPoll::Pending
                    }
                    DatabaseDocumentMountWork::Empty => DatabaseDocumentMountPoll::Pending,
                }
            };
            #[cfg(test)]
            if let Some(hook) = parked_hook {
                hook();
            }
            match outcome {
                DatabaseDocumentMountPoll::Pending => {
                    if self.wake_requested.swap(false, Ordering::AcqRel) {
                        continue;
                    }
                    if self.driver.compare_exchange(DatabaseDocumentMountDriver::Polling as u8, DatabaseDocumentMountDriver::Idle as u8, Ordering::AcqRel, Ordering::Acquire).is_err() {
                        return;
                    }
                    if self.wake_requested.swap(false, Ordering::AcqRel) {
                        self.queue_if_idle();
                    }
                    return;
                }
                DatabaseDocumentMountPoll::Continue => {}
                DatabaseDocumentMountPoll::Complete(result) => {
                    self.driver.store(DatabaseDocumentMountDriver::Terminal as u8, Ordering::Release);
                    self.complete(result);
                    return;
                }
            }
        }
    }

    fn complete(&self, result: Result<DatabaseDocumentMountReply, DbError>) {
        use std::sync::atomic::Ordering;
        let Some(registry) = self.registry.upgrade() else {
            return;
        };
        let mut fanout: [Option<(db_actor::ReplySender<Result<DatabaseDocumentMountReply, DbError>>, Result<DatabaseDocumentMountReply, DbError>)>; DATABASE_DOCUMENT_MOUNT_WAITERS] = std::array::from_fn(|_| None);
        {
            let mut registry = registry.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            let Some(DatabaseDocumentMountSlot::Opening { generation, waiters, .. }) = registry.slots.get_mut(&self.document) else {
                return;
            };
            if *generation != self.generation {
                return;
            }
            let waiters = std::mem::replace(waiters, std::array::from_fn(|_| None));
            let authority = result.as_ref().ok().cloned();
            if let Some(completion) = authority.as_ref() {
                registry.slots.insert(self.document.clone(), DatabaseDocumentMountSlot::Ready(completion.clone()));
            } else {
                registry.slots.remove(&self.document);
            }
            let error = result.err();
            for (slot, waiter) in waiters.into_iter().enumerate() {
                let Some(waiter) = waiter else { continue };
                let outcome = match (&authority, &error) {
                    (Some(completion), _) if waiter.policy != DatabaseDocumentMountPolicy::Create || waiter.create_claim => Ok(completion.clone()),
                    (Some(_), _) => Err(DbError::AlreadyExists(format!("document {} already exists", self.document))),
                    (_, Some(error)) => Err(error.clone()),
                    _ => Err(DbError::Internal("database document-mount terminal result missing".to_string())),
                };
                fanout[slot] = Some((waiter.reply, outcome));
            }
            drop(authority);
            drop(error);
            self.terminal.store(true, Ordering::Release);
        }
        for (reply, outcome) in fanout.into_iter().flatten() {
            reply.send(outcome);
        }
    }
}

//#region 🔖️Database
/// 🗄️ The catalog: owns the storage substrate, the shared config/capabilities/authz/observability
/// wiring every document actor is constructed with, and the registry of currently-open
/// `ArtifactAuthority` actors.
///
/// 🎯️ Design choice: the catalog registry itself is a plain `Mutex`-guarded `HashMap`, not a
/// separate `db_actor::Actor`-driven process. `Database`'s own public surface (`open`/
/// `create_document`/`document`/`catalog`/`health`/`shutdown`) is already synchronous per the
/// frozen contract, and per-document concurrency is already provided by each `ArtifactAuthority`'s
/// own dedicated thread — the catalog only ever needs to serialize document-registry mutations and
/// a catalog-root CAS write, which a `Mutex` does directly without the mailbox's priority-lane/
/// backpressure machinery (that machinery matters for a document's WAL under load, not a rare
/// catalog-root swap).
// 🔀️ `E` is the pluggable `Emit` sink — dedyn-emit-runtime, O1/R11(a): `open_with_emit`'s own doc
// ("a caller-supplied Emit sink, e.g. a `db_observe::WriterSink`") is exactly R11(a)'s "trivially
// generic" shape. Default is `db_observe::StructuredSink<db_observe::MemorySink>` — the concrete
// type `default_emit()` has always constructed — so every unparameterized `Database` reference
// (this crate's own `open`/`open_at`, plus `🌎️hub` and every other external caller, none of which
// ever names this type parameter) names the default. Replaces `Arc<dyn Emit>`.
pub struct Database<E: Emit + 'static = db_observe::StructuredSink<db_observe::MemorySink>> {
    storage: Arc<db_storage::DbBackend>,
    config: DbConfig,
    capabilities: DbCapabilities,
    emit: Arc<E>,
    health: Arc<db_observe::HealthRegistry>,
    catalog: Arc<Mutex<CatalogState>>,
    open_artifacts: Arc<Mutex<DatabaseDocumentMountRegistry>>,
    #[cfg(test)]
    mount_catalog_published_hook: Arc<Mutex<Option<DatabaseDocumentMountPublishedHook>>>,
    #[cfg(test)]
    mount_cleanup_fault_hook: Arc<Mutex<Option<DatabaseDocumentMountCleanupFaultHook>>>,
    #[cfg(test)]
    mount_parked_hook: Arc<Mutex<Option<DatabaseDocumentMountParkedHook>>>,
    closing_authority: Option<(String, Arc<db_artifact::ArtifactAuthority>)>,
    shutdown_emit_started: bool,
    shutdown_complete: bool,
    pool_use: Option<Arc<WorkerPoolUse>>,
    /// 🧵️ The process WorkerPool every document authority and submit bridge uses.
    /// Construction without this owner is intentionally impossible: no database path may execute
    /// blocking storage or authority work inline on its caller.
    pool: Arc<WorkerPool>,
}

// 🚫️async: E5 executor bridge — every `Database` method below is plain sync and drives its async
// storage/`ArtifactEngine` calls via `db_actor::block_on` (R4 clause 2: this crate's own db-actor
// thread bridges are sanctioned; `Database` is the facade the prior `db-trait-flip` packet already
// classified as thread-owning alongside `db_artifact`, per its report's "db_engine (per-submit
// bridge threads)"). Every `.wal()`/`.snapshot()`/`.catalog()`/`.index()`/`.payload()`/`.lease()`
// accessor call is `.await`ed inside the SAME `block_on`, never a bare synchronous call.
/// 🧲️ Filesystem database-open rejection retaining storage cleanup authority.
#[must_use = "database-open rejection must close its retained storage before exposing the cause"]
pub enum DatabaseOpenAtRejected {
    Storage(db_storage::DbStorageOpenRejected),
    Database { cause: DbError, cleanup_error: Option<DbError>, storage: Arc<db_storage::DbBackend> },
}

impl DatabaseOpenAtRejected {
    pub fn error(&self) -> &DbError {
        match self {
            Self::Storage(rejected) => rejected.error(),
            Self::Database { cause, .. } => cause,
        }
    }

    pub fn cleanup_error(&self) -> Option<&DbError> {
        match self {
            Self::Storage(rejected) => rejected.cleanup_error(),
            Self::Database { cleanup_error, .. } => cleanup_error.as_ref(),
        }
    }

    pub async fn retry_close(self) -> Result<DbError, Self> {
        match self {
            Self::Storage(rejected) => rejected.retry_close().await.map_err(Self::Storage),
            Self::Database { cause, cleanup_error: _, storage } => {
                let result = match storage.as_ref() {
                    #[cfg(all(feature = "fs", not(target_arch = "wasm32")))]
                    db_storage::DbBackend::Fs(storage) => storage.close().await,
                    _ => Err(DbError::Internal("database open-at rejection lost its filesystem storage".to_string())),
                };
                match result {
                    Ok(()) => Ok(cause),
                    Err(error) => Err(Self::Database { cause, cleanup_error: Some(error), storage }),
                }
            }
        }
    }
}

impl std::fmt::Debug for DatabaseOpenAtRejected {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.debug_struct("DatabaseOpenAtRejected").field("cause", self.error()).field("cleanup_error", &self.cleanup_error()).finish()
    }
}

impl Database {
    /// 🚀️ The frozen entry point: opens (or initializes, if `storage` is fresh) a `Database`
    /// over an arbitrary `Arc<db_storage::DbBackend>` backend, wired with the default in-memory emit sink.
    pub async fn open(pool: Arc<WorkerPool>, config: DbConfig, storage: Arc<db_storage::DbBackend>) -> Result<Database, DbError> {
        Database::open_with(pool, config, storage, default_emit().await).await
    }

    /// 🚀️ The zero-touch filesystem entry point. The caller supplies the process pool
    /// before storage construction, so opening can never take a pool-less inline path.
    pub async fn open_at(pool: Arc<WorkerPool>, root: &std::path::Path, profile: Profile) -> Result<Database, DatabaseOpenAtRejected> {
        let fs = db_storage::FsStorage::open(pool.clone(), root).await.map_err(DatabaseOpenAtRejected::Storage)?;
        let storage: Arc<db_storage::DbBackend> = Arc::new(db_storage::DbBackend::Fs(fs));
        match Database::open(pool, DbConfig::for_profile(profile), storage.clone()).await {
            Ok(database) => Ok(database),
            Err(cause) => Err(DatabaseOpenAtRejected::Database { cause, cleanup_error: None, storage }),
        }
    }

    /// 🚀️ Like `open`, but with a caller-supplied `Emit` sink (e.g. a `db_observe::WriterSink`
    /// over a real file) instead of the default in-memory one.
    // 🔀️ dedyn-emit-runtime, O1/R11(a): generic over `E: Emit` (the function's own type param, not
    // `Database`'s default) so the returned `Database<E>` carries the caller's concrete sink type —
    // this fn has zero callers anywhere in the repo today (public, documented extension seam per
    // `open_with_emit`'s own doc).
    pub async fn open_with_emit<E: Emit + 'static>(pool: Arc<WorkerPool>, config: DbConfig, storage: Arc<db_storage::DbBackend>, emit: Arc<E>) -> Result<Database<E>, DbError> {
        Database::open_with(pool, config, storage, emit).await
    }
}

// 🔀️ dedyn-emit-runtime, O1/R11(a): every method below reads/writes `self.emit`, so this whole
// block is generic over `E: Emit`; Rust resolves `open`'s `Database::open_with(..)` call by inferring
// `E` from `default_emit()`'s concrete return type.
impl<E: Emit + 'static> Database<E> {
    fn require_open_use(&self) -> Result<Arc<WorkerPoolUse>, DbError> {
        if self.shutdown_complete {
            return Err(DbError::Closed);
        }
        self.pool_use.clone().ok_or(DbError::Closed)
    }

    /// 🧵️ Admits the exact storage owner before probing one backend capability future on I/O.
    pub fn open_retained(pool: Arc<WorkerPool>, storage: Arc<db_storage::DbBackend>) -> Result<DatabaseCapabilityOpenFuture, DatabaseCapabilityOpenRejected> {
        DatabaseCapabilityOpenFuture::try_submit(pool, storage)
    }

    /// 🗂️ Admits the exact storage/root-key owners before one catalog backend read on I/O.
    pub fn open_catalog_read_retained(pool: Arc<WorkerPool>, storage: Arc<db_storage::DbBackend>) -> Result<DatabaseCatalogReadFuture, DatabaseCatalogReadRejected> {
        DatabaseCatalogReadFuture::try_submit(pool, storage, DatabaseCatalogRootKey::root())
    }

    /// 🌱️ Admits the exact storage/catalog-page/fence owners before the initial CAS reaches I/O.
    pub fn open_catalog_bootstrap_retained(pool: Arc<WorkerPool>, storage: Arc<db_storage::DbBackend>, pages: db_storage::DbIoPages) -> Result<DatabaseCatalogBootstrapFuture, DatabaseCatalogBootstrapRejected> {
        DatabaseCatalogBootstrapFuture::try_submit(pool, storage, pages, EpochFence::INITIAL)
    }

    async fn open_with(pool: Arc<WorkerPool>, config: DbConfig, storage: Arc<db_storage::DbBackend>, emit: Arc<E>) -> Result<Database<E>, DbError> {
        let pool_use = pool.acquire_use().map_err(|error| DbError::Unavailable(format!("database WorkerPool use rejected: {error:?}")))?;
        let capability_probe = match DatabaseCapabilityOpenFuture::try_prepare_with_use(pool.clone(), pool_use.clone(), storage, true) {
            Ok(probe) => probe,
            Err(rejected) => return Err(rejected.close_and_take_error()),
        };
        let (storage, storage_capabilities) = capability_probe.await?.into_parts();
        let capabilities = DbCapabilities {
            // 🧩️ Extension seam: real, honest today — see module doc on why preview/live-query
            // aren't reachable through `ArtifactAuthority`'s current mailbox surface, and why
            // `db_cluster` is still an empty stub upstream of this wave.
            preview: false,
            historical_query: true,
            live_query: false,
            cluster: false,
            max_durability: std::cmp::min(storage_capabilities.max_durability, config.capabilities.max_durability),
        };

        let health = Arc::new(db_observe::HealthRegistry::new());
        health.set("db_engine.storage", if storage_capabilities.durable { db_observe::HealthState::Healthy } else { db_observe::HealthState::Degraded("storage backend is not durable".to_string()) });

        let catalog_probe = match DatabaseCatalogReadFuture::try_prepare_with_use(pool.clone(), pool_use.clone(), storage, DatabaseCatalogRootKey::root(), true) {
            Ok(probe) => probe,
            Err(rejected) => return Err(rejected.close_and_take_error(pool.clone())),
        };
        let (storage, _catalog_key, catalog_root) = catalog_probe.await?.into_parts();
        let (storage, epoch, entries) = match catalog_root? {
            Some((bytes, epoch)) => {
                let prepared = db_storage::db_io_prepare_platform(&bytes)?.await?;
                (storage, epoch, decode_catalog(prepared.as_slice()).await?)
            }
            None => {
                let pages = encode_catalog_pages(&[]).await?;
                let bootstrap = match DatabaseCatalogBootstrapFuture::try_prepare_with_use(pool.clone(), pool_use.clone(), storage, pages, DatabaseCatalogBootstrapKey::root(), EpochFence::INITIAL, true) {
                    Ok(bootstrap) => bootstrap,
                    Err(rejected) => return Err(rejected.close_and_take_error()),
                };
                let result = bootstrap.await?;
                let (retained_storage, _catalog_key, expected, actual) = match result.into_parts() {
                    Ok(parts) => parts,
                    Err(owner) => {
                        drop(owner);
                        return Err(DbError::Internal("database catalog-bootstrap result was incomplete".to_string()));
                    }
                };
                if expected != EpochFence::INITIAL {
                    return Err(DbError::Internal("database catalog-bootstrap returned the wrong expected fence".to_string()));
                }
                let epoch = actual?;
                (retained_storage, epoch, Vec::new())
            }
        };
        health.set("db_engine.catalog", db_observe::HealthState::Healthy);

        emit.emit(EmitEvent::new("db_engine.database_opened").field("documents", EmitField::U64(entries.len() as u64))).await;

        Ok(Database {
            storage,
            config,
            capabilities,
            emit,
            health,
            catalog: Arc::new(Mutex::new(CatalogState { epoch, revision: 1, entries: Arc::new(entries), pending: None })),
            open_artifacts: Arc::new(Mutex::new(DatabaseDocumentMountRegistry::new())),
            #[cfg(test)]
            mount_catalog_published_hook: Arc::new(Mutex::new(None)),
            #[cfg(test)]
            mount_cleanup_fault_hook: Arc::new(Mutex::new(None)),
            #[cfg(test)]
            mount_parked_hook: Arc::new(Mutex::new(None)),
            closing_authority: None,
            shutdown_emit_started: false,
            shutdown_complete: false,
            pool_use: Some(pool_use),
            pool,
        })
    }

    /// ⚙️ Builds one `ArtifactEngineConfig`: this database's own `limits` and preview TTL, and
    /// `..db_artifact::ArtifactEngineConfig::default()` for every other field (`security`/`emit`/
    /// `projections`) — this crate has no opinion on those (`db_artifact`'s own real
    /// `db_security::SecurityGate`-backed default policy is permissive single-tenant), and the spread keeps
    /// this call site correct across further additive growth without another coordinated edit.
    fn document_engine_config(&self) -> db_artifact::ArtifactEngineConfig {
        db_artifact::ArtifactEngineConfig { limits: self.config.limits.clone(), preview_ttl_ms: self.config.limits.max_preview_ttl_ms, ..db_artifact::ArtifactEngineConfig::default() }
    }

    fn retained_mount_rejection(rejected: db_artifact::ArtifactEngineOpenRejected, resume: Option<DatabaseDocumentMountFuture>) -> DatabaseDocumentMountFailure {
        DatabaseDocumentMountFailure::Retained { rejected, resume }
    }

    async fn refresh_catalog_document(pool: Arc<WorkerPool>, storage: Arc<db_storage::DbBackend>, catalog: Arc<Mutex<CatalogState>>, document: &protocol::ArtifactId) -> Result<bool, DbError> {
        let read = match DatabaseCatalogReadFuture::try_submit(pool.clone(), storage, DatabaseCatalogRootKey::root()) {
            Ok(read) => read,
            Err(rejected) => return Err(rejected.close_and_take_error(pool)),
        };
        let result = read.await?;
        let (_storage, _key, root) = result.into_parts();
        let Some((bytes, epoch)) = root? else { return Ok(false) };
        let prepared = db_storage::db_io_prepare_platform(&bytes)?.await?;
        let entries = decode_catalog(prepared.as_slice()).await?;
        let known = entries.iter().any(|entry| entry.document == *document);
        let mut state = catalog.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if epoch.epoch >= state.epoch.epoch {
            state.epoch = epoch;
            state.revision = state.revision.checked_add(1).ok_or(DbError::LimitExceeded("database catalog refresh revision"))?;
            state.entries = Arc::new(entries);
            state.pending = None;
        }
        Ok(known)
    }

    async fn publish_mount_catalog(_live: DatabaseMountFutureLiveGuardV1, pool: Arc<WorkerPool>, pool_use: Arc<WorkerPoolUse>, storage: Arc<db_storage::DbBackend>, catalog: Arc<Mutex<CatalogState>>, document: protocol::ArtifactId) -> Result<(), DbError> {
        let transaction = match DatabaseCreateCatalogFuture::try_prepare_with_use(pool, pool_use, catalog, storage, document, true) {
            Ok(transaction) => transaction,
            Err(rejected) => return Err(rejected.close_and_take_error()),
        };
        let result = transaction.await?;
        let (_storage, _document, _expected, actual) = result.into_parts().map_err(|_| DbError::LimitExceeded("database create-catalog result owner"))?;
        actual.map(|_| ())
    }

    async fn run_open_document_mount(
        _live: DatabaseMountFutureLiveGuardV1,
        pool: Arc<WorkerPool>,
        pool_use: Arc<WorkerPoolUse>,
        storage: Arc<db_storage::DbBackend>,
        document: protocol::ArtifactId,
        config: db_artifact::ArtifactEngineConfig,
        mailbox_capacities: MailboxCapacities,
        emit: Arc<E>,
    ) -> Result<DatabaseDocumentMountReply, DatabaseDocumentMountFailure> {
        let open_document = document.clone();
        let opened_at_ms = now_ms().await;
        let authority = match db_artifact::ArtifactAuthority::spawn_with_pool_use(
            pool,
            pool_use,
            move || async move { db_artifact::ArtifactEngine::open_retained(open_document, storage, config, opened_at_ms).await.map(|(engine, _)| Box::new(engine)) },
            mailbox_capacities,
        )
        .await
        {
            Ok(authority) => authority,
            Err(rejected) => return Err(Self::retained_mount_rejection(rejected, None)),
        };
        emit.emit(EmitEvent::new("db_engine.document_opened").with_document(to_core_document_id(&document).await)).await;
        Ok(DatabaseDocumentMountReply { authority: Arc::new(authority), handles: Arc::new(std::sync::atomic::AtomicUsize::new(0)) })
    }

    async fn run_document_mount(
        _live: DatabaseMountFutureLiveGuardV1,
        predecessor: Option<db_actor::ReplyReceiver<()>>,
        pool: Arc<WorkerPool>,
        pool_use: Arc<WorkerPoolUse>,
        storage: Arc<db_storage::DbBackend>,
        catalog: Arc<Mutex<CatalogState>>,
        document: protocol::ArtifactId,
        policy: DatabaseDocumentMountPolicy,
        catalog_known: bool,
        create_config: db_artifact::ArtifactEngineConfig,
        open_config: db_artifact::ArtifactEngineConfig,
        mailbox_capacities: MailboxCapacities,
        emit: Arc<E>,
        #[cfg(test)] mount_catalog_published_hook: Arc<Mutex<Option<DatabaseDocumentMountPublishedHook>>>,
    ) -> Result<DatabaseDocumentMountReply, DatabaseDocumentMountFailure> {
        if let Some(predecessor) = predecessor {
            let _ = predecessor.await;
        }
        let mut create = !catalog_known && policy != DatabaseDocumentMountPolicy::Open;
        if create {
            if let Err(error) = Self::publish_mount_catalog(DatabaseMountFutureLiveGuardV1::new(), pool.clone(), pool_use.clone(), storage.clone(), catalog.clone(), document.clone()).await {
                if policy != DatabaseDocumentMountPolicy::Ensure || !matches!(error, DbError::AlreadyExists(_) | DbError::Fenced { .. }) {
                    return Err(error.into());
                }
                if !Self::refresh_catalog_document(pool.clone(), storage.clone(), catalog.clone(), &document).await? {
                    return Err(error.into());
                }
                create = false;
            }
            #[cfg(test)]
            if create {
                if let Some(hook) = mount_catalog_published_hook.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
                    hook(&document);
                }
            }
        }

        let authority = if create {
            let create_pool = pool.clone();
            let create_storage = storage.clone();
            let create_document = document.clone();
            let created_at_ms = now_ms().await;
            match db_artifact::ArtifactAuthority::spawn_with_pool_use(create_pool, pool_use.clone(), move || async move { db_artifact::ArtifactEngine::create_retained(create_document, create_storage, create_config, created_at_ms).await.map(Box::new) }, mailbox_capacities).await {
                Ok(authority) => authority,
                Err(rejected) => {
                    let retry_open = policy == DatabaseDocumentMountPolicy::Ensure && matches!(rejected.error(), DbError::AlreadyExists(_));
                    let resume = retry_open.then(|| Box::pin(Self::run_open_document_mount(DatabaseMountFutureLiveGuardV1::new(), pool.clone(), pool_use.clone(), storage.clone(), document.clone(), open_config, mailbox_capacities, emit.clone())) as DatabaseDocumentMountFuture);
                    return Err(Self::retained_mount_rejection(rejected, resume));
                }
            }
        } else {
            return Self::run_open_document_mount(DatabaseMountFutureLiveGuardV1::new(), pool, pool_use, storage, document, open_config, mailbox_capacities, emit).await;
        };
        emit.emit(EmitEvent::new("db_engine.document_created").with_document(to_core_document_id(&document).await)).await;
        Ok(DatabaseDocumentMountReply { authority: Arc::new(authority), handles: Arc::new(std::sync::atomic::AtomicUsize::new(0)) })
    }

    /// 🔁️ Mounts until a handle is adopted. A mount whose document went idle and started closing
    /// between its reply and its adoption mounts again, then as an open of the document it created.
    async fn mount_document(&self, document: protocol::ArtifactId, policy: DatabaseDocumentMountPolicy) -> Result<ArtifactHandle, DatabaseDocumentOpenRejected> {
        let mut policy = policy;
        loop {
            if let Some(handle) = self.mount_document_once(document.clone(), policy).await? {
                return Ok(handle);
            }
            if policy == DatabaseDocumentMountPolicy::Create {
                policy = DatabaseDocumentMountPolicy::Open;
            }
        }
    }

    fn adopt_mount(&self, document: &protocol::ArtifactId, handles: &Arc<std::sync::atomic::AtomicUsize>, registry: &DatabaseDocumentMountRegistry) -> Option<ArtifactHandleLease> {
        match registry.slots.get(&document.0) {
            Some(DatabaseDocumentMountSlot::Ready(ready)) if Arc::ptr_eq(&ready.handles, handles) => Some(ArtifactHandleLease::new(handles.clone(), Arc::downgrade(&self.open_artifacts), document.0.clone())),
            _ => None,
        }
    }

    async fn mount_document_once(&self, document: protocol::ArtifactId, policy: DatabaseDocumentMountPolicy) -> Result<Option<ArtifactHandle>, DatabaseDocumentOpenRejected> {
        let pool_use = self.require_open_use()?;
        let _pool_use_site = DatabasePoolUseSiteGuardV1::new(&DATABASE_POOL_USE_MOUNT_WAIT_LIVE);
        let catalog_known = self.catalog.lock().expect("db_engine: catalog mutex poisoned").entries.iter().any(|entry| entry.document == document);
        let create_config = self.document_engine_config();
        let open_config = self.document_engine_config();
        let (reply, owner) = {
            let mut registry = self.open_artifacts.lock().expect("db_engine: open_artifacts mutex poisoned");
            if let Some(DatabaseDocumentMountSlot::Ready(completion)) = registry.slots.get(&document.0) {
                if policy == DatabaseDocumentMountPolicy::Create {
                    return Err(DbError::AlreadyExists(format!("document {} already exists", document.0)).into());
                }
                let completion = completion.clone();
                let lease = self.adopt_mount(&document, &completion.handles, &registry);
                drop(registry);
                return Ok(lease.map(|lease| ArtifactHandle { authority: completion.authority, _lease: lease, document, pool: self.pool.clone() }));
            }
            if let Some(DatabaseDocumentMountSlot::Opening { generation, owner, waiters }) = registry.slots.get_mut(&document.0) {
                let Some(slot) = waiters.iter().position(Option::is_none) else {
                    return Err(DbError::Unavailable("database document-mount waiter capacity exhausted".to_string()).into());
                };
                let generation = *generation;
                let (reply, raw_receiver) = db_actor::oneshot();
                waiters[slot] = Some(DatabaseDocumentMountWaiter { policy, create_claim: false, reply });
                (DatabaseDocumentMountWait { receiver: raw_receiver, registry: Arc::downgrade(&self.open_artifacts), document: document.0.clone(), generation, slot, resolved: false }, Some(owner.clone()))
            } else {
                if policy == DatabaseDocumentMountPolicy::Create && catalog_known {
                    return Err(DbError::AlreadyExists(format!("document {} already exists", document.0)).into());
                }
                if policy == DatabaseDocumentMountPolicy::Open && !catalog_known {
                    return Err(DbError::NotFound(format!("document {} not found", document.0)).into());
                }
                let generation = registry.take_generation()?;
                let predecessor = match registry.slots.remove(&document.0) {
                    Some(DatabaseDocumentMountSlot::Closing { terminal }) => Some(terminal),
                    Some(other) => {
                        registry.slots.insert(document.0.clone(), other);
                        return Err(DbError::Internal("database document-mount slot changed under its lock".to_string()).into());
                    }
                    None => None,
                };
                let (reply, raw_receiver) = db_actor::oneshot();
                let future = Box::pin(Self::run_document_mount(
                    DatabaseMountFutureLiveGuardV1::new(),
                    predecessor,
                    self.pool.clone(),
                    pool_use,
                    self.storage.clone(),
                    self.catalog.clone(),
                    document.clone(),
                    policy,
                    catalog_known,
                    create_config,
                    open_config,
                    self.config.mailbox_capacities,
                    self.emit.clone(),
                    #[cfg(test)]
                    self.mount_catalog_published_hook.clone(),
                ));
                let owner = DatabaseDocumentMountOwner::new(
                    self.pool.clone(),
                    Arc::downgrade(&self.open_artifacts),
                    document.0.clone(),
                    generation,
                    future,
                    #[cfg(test)]
                    self.mount_cleanup_fault_hook.clone(),
                    #[cfg(test)]
                    self.mount_parked_hook.clone(),
                );
                let mut waiters = std::array::from_fn(|_| None);
                waiters[0] = Some(DatabaseDocumentMountWaiter { policy, create_claim: policy == DatabaseDocumentMountPolicy::Create, reply });
                registry.slots.insert(document.0.clone(), DatabaseDocumentMountSlot::Opening { generation, owner: owner.clone(), waiters });
                (DatabaseDocumentMountWait { receiver: raw_receiver, registry: Arc::downgrade(&self.open_artifacts), document: document.0.clone(), generation, slot: 0, resolved: false }, Some(owner))
            }
        };
        if let Some(owner) = owner {
            owner.request_drive(false);
        }
        let result = reply.await.map_err(DatabaseDocumentOpenRejected::Database)?;
        let result = result.map_err(DatabaseDocumentOpenRejected::Database)?;
        let lease = {
            let registry = self.open_artifacts.lock().expect("db_engine: open_artifacts mutex poisoned");
            self.adopt_mount(&document, &result.handles, &registry)
        };
        Ok(lease.map(|lease| ArtifactHandle { authority: result.authority, _lease: lease, document, pool: self.pool.clone() }))
    }

    /// 🪴️ Admits the exact create-document catalog transaction before any catalog owner is copied.
    pub fn create_document_catalog_retained(&self, document: protocol::ArtifactId) -> Result<DatabaseCreateCatalogFuture, DatabaseRetainedActivityRejected<DatabaseCreateCatalogRejected>> {
        let pool_use = self.require_open_use().map_err(DatabaseRetainedActivityRejected::Closed)?;
        DatabaseCreateCatalogFuture::try_prepare_with_use(self.pool.clone(), pool_use, self.catalog.clone(), self.storage.clone(), document, true).map_err(DatabaseRetainedActivityRejected::Retained)
    }

    /// 🌱️ The frozen `create_document`: mints a brand-new document, durably records it in the
    /// catalog root (CAS-fenced), spawns its `ArtifactAuthority`, and returns a live handle.
    pub async fn create_document(&self, spec: ArtifactSpec) -> Result<ArtifactHandle, DatabaseDocumentOpenRejected> {
        self.mount_document(spec.document, DatabaseDocumentMountPolicy::Create).await
    }

    /// 🪢️ Joins or installs the exact retained first-mount owner for one document.
    pub async fn ensure_document(&self, id: &protocol::ArtifactId) -> Result<ArtifactHandle, DatabaseDocumentOpenRejected> {
        self.mount_document(id.clone(), DatabaseDocumentMountPolicy::Ensure).await
    }

    /// 📄️ The frozen `document`: returns a live handle to an already-cataloged document,
    /// reusing an already-open `ArtifactAuthority` if one exists, else recovering it fresh from its
    /// WAL.
    pub async fn document(&self, id: &protocol::ArtifactId) -> Result<ArtifactHandle, DatabaseDocumentOpenRejected> {
        self.mount_document(id.clone(), DatabaseDocumentMountPolicy::Open).await
    }

    /// 📇️ The frozen `catalog`: a point-in-time read of every document this `Database`
    /// knows about.
    pub async fn catalog(&self) -> CatalogView {
        let entries = {
            let catalog = self.catalog.lock().expect("db_engine: catalog mutex poisoned");
            Arc::clone(&catalog.entries)
        };
        CatalogView { artifacts: entries.as_ref().clone() }
    }

    /// 🩺️ The frozen `health`: this `Database`'s `HealthRegistry` snapshot plus its own open
    /// document count.
    pub async fn health(&self) -> DbHealth {
        DbHealth { report: self.health.report(), open_artifacts: self.open_artifacts.lock().expect("db_engine: open_artifacts mutex poisoned").ready_count() }
    }

    /// 🚪️ Advances at most one retained shutdown owner. Cancellation, deadline, and every error
    /// return leave the exact authority mounted on this Database for retry.
    pub async fn shutdown_step(&mut self, control: &DatabaseShutdownControl) -> Result<DatabaseShutdownProgress, DbError> {
        if self.shutdown_complete {
            return Ok(DatabaseShutdownProgress::Complete);
        }
        if control.interrupted() {
            return Ok(DatabaseShutdownProgress::Interrupted);
        }
        if let Some((_, authority)) = self.closing_authority.as_ref() {
            if !authority.shutdown_step() {
                if let Some(progress) = authority.close_retry_progress().filter(db_artifact::ArtifactCloseRetryProgress::is_blocked) {
                    return Ok(DatabaseShutdownProgress::Blocked(DatabaseShutdownBlock::ArtifactClose(progress)));
                }
                return Ok(DatabaseShutdownProgress::Progress { phase: DatabaseShutdownPhase::Authority, remaining_authorities: self.open_artifacts.lock().expect("db_engine: open_artifacts mutex poisoned").len() + 1 });
            }
            self.closing_authority.take();
            return Ok(DatabaseShutdownProgress::Progress { phase: DatabaseShutdownPhase::Authority, remaining_authorities: self.open_artifacts.lock().expect("db_engine: open_artifacts mutex poisoned").len() });
        }
        let closing = {
            let mut registry = self.open_artifacts.lock().expect("db_engine: open_artifacts mutex poisoned");
            let document = registry.slots.iter().find_map(|(document, slot)| matches!(slot, DatabaseDocumentMountSlot::Closing { .. }).then(|| document.clone()));
            document.and_then(|document| registry.slots.remove(&document).map(|slot| (document, slot)))
        };
        if let Some((document, slot)) = closing {
            let DatabaseDocumentMountSlot::Closing { mut terminal } = slot else { return Err(DbError::Internal("selected closing mount was not closing".to_string())) };
            let retired = std::future::poll_fn(|context| std::task::Poll::Ready(std::pin::Pin::new(&mut terminal).poll(context).is_ready())).await;
            if !retired {
                self.open_artifacts.lock().expect("db_engine: open_artifacts mutex poisoned").slots.insert(document, DatabaseDocumentMountSlot::Closing { terminal });
                semio_framework_async::yield_once().await;
            }
            return Ok(DatabaseShutdownProgress::Progress { phase: DatabaseShutdownPhase::Authority, remaining_authorities: self.open_artifacts.lock().expect("db_engine: open_artifacts mutex poisoned").len() });
        }
        let opening = {
            let registry = self.open_artifacts.lock().expect("db_engine: open_artifacts mutex poisoned");
            registry.slots.values().find_map(|slot| match slot {
                DatabaseDocumentMountSlot::Opening { owner, .. } => Some(owner.clone()),
                DatabaseDocumentMountSlot::Ready(_) | DatabaseDocumentMountSlot::Closing { .. } => None,
            })
        };
        if let Some(owner) = opening {
            if let Some(kind) = owner.scheduler_fault() {
                return Ok(DatabaseShutdownProgress::Blocked(DatabaseShutdownBlock::Executor(kind)));
            }
            owner.drive();
            semio_framework_async::yield_once().await;
            return Ok(DatabaseShutdownProgress::Progress { phase: DatabaseShutdownPhase::Authority, remaining_authorities: self.open_artifacts.lock().expect("db_engine: open_artifacts mutex poisoned").len() });
        }
        let next = {
            let registry = self.open_artifacts.lock().expect("db_engine: open_artifacts mutex poisoned");
            registry
                .slots
                .iter()
                .filter_map(|(document, slot)| match slot {
                    DatabaseDocumentMountSlot::Ready(completion) if completion.handles.load(std::sync::atomic::Ordering::Acquire) == 0 => Some(document.clone()),
                    _ => None,
                })
                .min()
        };
        if let Some(document) = next {
            let slot = self.open_artifacts.lock().expect("db_engine: open_artifacts mutex poisoned").slots.remove(&document).expect("selected shutdown authority disappeared");
            let DatabaseDocumentMountSlot::Ready(completion) = slot else { return Err(DbError::Internal("selected shutdown mount was not ready".to_string())) };
            self.closing_authority = Some((document, completion.authority));
            return Ok(DatabaseShutdownProgress::Progress { phase: DatabaseShutdownPhase::Authority, remaining_authorities: self.open_artifacts.lock().expect("db_engine: open_artifacts mutex poisoned").len() + 1 });
        }
        let shared_authorities = self.open_artifacts.lock().expect("db_engine: open_artifacts mutex poisoned").len();
        if shared_authorities != 0 {
            return Ok(DatabaseShutdownProgress::Blocked(DatabaseShutdownBlock::Authorities(shared_authorities)));
        }
        if !self.shutdown_emit_started {
            self.shutdown_emit_started = true;
            self.emit.emit(EmitEvent::new("db_engine.database_shutdown")).await;
            return Ok(DatabaseShutdownProgress::Progress { phase: DatabaseShutdownPhase::Emit, remaining_authorities: 0 });
        }
        if self.pool_use.as_ref().is_some_and(|pool_use| Arc::strong_count(pool_use) != 1) {
            if let Some(progress) = db_artifact::artifact_close_retry_progress(&self.pool).filter(db_artifact::ArtifactCloseRetryProgress::is_blocked) {
                return Ok(DatabaseShutdownProgress::Blocked(DatabaseShutdownBlock::ArtifactClose(progress)));
            }
            return Ok(DatabaseShutdownProgress::Progress { phase: DatabaseShutdownPhase::PoolUse, remaining_authorities: 0 });
        }
        self.pool_use.take();
        self.shutdown_complete = true;
        Ok(DatabaseShutdownProgress::Complete)
    }

    /// 🔂️ Grants every faulted artifact close this Database still retires (its closing authority and the
    /// dropped authorities retiring on its pool) a fresh bounded retry budget.
    pub fn readmit_artifact_close_retries(&self) -> usize {
        let closing = self.closing_authority.as_ref().is_some_and(|(_, authority)| authority.readmit_close_retry());
        usize::from(closing) + db_artifact::artifact_close_retry_readmit(&self.pool)
    }

    /// 🛑️ Stops the automatic retries of every faulted artifact close this Database still retires.
    pub fn cancel_artifact_close_retries(&self) -> usize {
        let closing = self.closing_authority.as_ref().is_some_and(|(_, authority)| authority.cancel_close_retry());
        usize::from(closing) + db_artifact::artifact_close_retry_cancel(&self.pool)
    }

    /// 🛬️ Drives bounded shutdown steps to a terminal acknowledgement while borrowing the exact
    /// Database. Error and future cancellation therefore preserve caller retry authority. Each call
    /// is the product retry owner of faulted artifact closes: it re-admits exhausted or cancelled
    /// ones once, lets the pool timer drive their bounded backoff, reports an exhausted budget as a
    /// terminal error and cancels the retries when the caller cancels.
    pub async fn shutdown(&mut self, control: &DatabaseShutdownControl) -> Result<(), DbError> {
        self.readmit_artifact_close_retries();
        let mut reached = None;
        loop {
            match self.shutdown_step(control).await? {
                DatabaseShutdownProgress::Progress { phase, .. } => {
                    reached = Some(phase);
                    semio_framework_async::yield_once().await;
                }
                DatabaseShutdownProgress::Blocked(DatabaseShutdownBlock::Authorities(count)) => {
                    return Err(DbError::Conflict(format!("database shutdown retains {count} shared artifact authorities")));
                }
                DatabaseShutdownProgress::Blocked(DatabaseShutdownBlock::Executor(kind)) => {
                    return Err(DbError::Unavailable(format!("database shutdown retains a non-runnable document-mount job: {kind:?}")));
                }
                DatabaseShutdownProgress::Blocked(DatabaseShutdownBlock::ArtifactClose(progress)) => {
                    return Err(DbError::Unavailable(format!("database shutdown retains a faulted artifact close after {} of {} retries ({:?})", progress.attempts, progress.limit, progress.state)));
                }
                DatabaseShutdownProgress::Interrupted => {
                    if control.cancelled.load(std::sync::atomic::Ordering::Acquire) {
                        self.cancel_artifact_close_retries();
                    }
                    return Err(control.interruption_error(DatabaseShutdownInterruptionWitness {
                        phase: reached,
                        open_artifacts: self.open_artifacts.lock().unwrap_or_else(std::sync::PoisonError::into_inner).len(),
                        emit_started: self.shutdown_emit_started,
                        pool_use_owners: self.pool_use.as_ref().map_or(0, Arc::strong_count),
                        retained_slots: DatabaseRetainedPoolUseCensus::observe(),
                    }));
                }
                DatabaseShutdownProgress::Complete => return Ok(()),
            }
        }
    }

    /// 🧰️ What this `Database` instance negotiated at `open` time.
    pub async fn capabilities(&self) -> DbCapabilities {
        self.capabilities
    }

    /// 🔌️ The underlying storage substrate this `Database` was opened with — an escape
    /// hatch for callers below the document-actor boundary that need direct `PayloadStorage`/
    /// `WalStorage` access (e.g. `os-semio_hub`'s content-addressed blob routes, or a wire-v2 semio_hub
    /// session driving `db_sync::handle_frontier_advertise` directly). Additive: not part of the
    /// contract-frozen `Database` API surface listed in `contract.md`'s "Stable API" block, so it
    /// carries no compatibility promise beyond this crate's own semver.
    pub async fn storage(&self) -> Arc<db_storage::DbBackend> {
        self.storage.clone()
    }

    /// 🧵️ Queues compaction on the document actor that already owns its WAL writer.
    pub async fn compact_document_retained(
        &self,
        document: &protocol::ArtifactId,
        holder: db_storage::DbIoText,
        consolidate_snapshots: bool,
        now_ms: u64,
        cancelled: Arc<std::sync::atomic::AtomicBool>,
    ) -> Result<ArtifactCompactionFuture, DatabaseDocumentOpenRejected> {
        Ok(self.document(document).await?.compact_retained(holder, consolidate_snapshots, db_compact::CompactionBudget::default(), now_ms, cancelled))
    }

    /// 🧹️ Mounts one retained compaction authority and awaits only its terminal witness.
    pub async fn compact_document(&self, document: &protocol::ArtifactId, holder: &str, consolidate_snapshots: bool) -> Result<db_compact::CompactionReport, DatabaseDocumentOpenRejected> {
        let holder = db_storage::DbIoText::try_from_str(holder)?;
        let requested_at_ms = now_ms().await;
        let cancelled = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let result = self.compact_document_retained(document, holder, consolidate_snapshots, requested_at_ms, cancelled).await?.await.map_err(DatabaseDocumentOpenRejected::Database)?;
        result.map_err(DatabaseDocumentOpenRejected::Database)
    }

    /// 👋️ Pre-admits the exact sync-hello owners before mounting shared-pool I/O work.
    pub fn hello_retained(
        &self,
        document: ArtifactId,
        hello_frontier: Option<protocol::RuntimeFrontierSummary>,
        session_id: String,
        origin: protocol::ActorId,
        snapshot_chunk_bytes: usize,
    ) -> Result<db_sync::DatabaseSyncHelloFuture, DatabaseRetainedActivityRejected<db_sync::DatabaseSyncHelloRejected>> {
        let pool_use = self.require_open_use().map_err(DatabaseRetainedActivityRejected::Closed)?;
        db_sync::DatabaseSyncHelloFuture::try_submit_with_use(self.pool.clone(), pool_use, self.storage.clone(), document, hello_frontier, session_id, origin, snapshot_chunk_bytes).map_err(DatabaseRetainedActivityRejected::Retained)
    }

    /// 📡️ Mounts one retained hello authority and returns its backpressured frame session. A hello
    /// that finds every admission slot taken waits for one (at most [`DATABASE_HELLO_ADMISSION_WAIT_MS`])
    /// instead of refusing its socket; any other refusal is answered at once.
    pub async fn hello(
        &self,
        document: protocol::ArtifactId,
        hello_frontier: Option<protocol::RuntimeFrontierSummary>,
        session_id: String,
        origin: protocol::ActorId,
        snapshot_chunk_bytes: usize,
    ) -> Result<db_sync::DatabaseSyncHelloSession, DbError> {
        let document = to_core_document_id(&document).await;
        let deadline_ms = self.pool.now_ms().saturating_add(DATABASE_HELLO_ADMISSION_WAIT_MS);
        loop {
            let hello = match self.hello_retained(document.clone(), hello_frontier.clone(), session_id.clone(), origin.clone(), snapshot_chunk_bytes) {
                Ok(hello) => hello,
                Err(DatabaseRetainedActivityRejected::Closed(error)) => return Err(error),
                Err(DatabaseRetainedActivityRejected::Retained(rejected)) => {
                    let saturated = rejected.admission_saturated();
                    let error = rejected.close_and_take_error();
                    if !saturated {
                        return Err(error);
                    }
                    db_sync::DatabaseSyncHelloAdmissionReady::new(self.pool.clone(), deadline_ms).await?;
                    continue;
                }
            };
            return hello.await?.close_and_take_session();
        }
    }
}

/// ⏳️ How long [`Database::hello`] waits for a sync-hello admission slot before it answers the
/// refusal: the hub's document-socket frame deadline.
pub const DATABASE_HELLO_ADMISSION_WAIT_MS: u64 = 30_000;
//#endregion 🔖️Database

//#region 🔖️ArtifactHandle
const ARTIFACT_SUBMIT_OPERATION_ITEMS: usize = 64;
const ARTIFACT_SUBMIT_PAGE_BYTES: u64 = 16 * 1024;
/// 📐️ One submit holds any batch the document backbone declares legal (`protocol::DOCUMENT_BACKBONE_BATCH_MAXIMUM_*`): a
/// writer's whole post-cut outbox arrives as one batch and must commit, so the envelope, nested-item and byte credits are the
/// declaration's own maxima — never a smaller engine-side cap a declared batch could hit.
const ARTIFACT_SUBMIT_BATCH_ITEMS: usize = protocol::DOCUMENT_BACKBONE_BATCH_MAXIMUM_ENVELOPES;
const ARTIFACT_SUBMIT_NESTED_ITEMS: usize = protocol::DOCUMENT_BACKBONE_BATCH_MAXIMUM_ENVELOPES + protocol::DOCUMENT_BACKBONE_BATCH_MAXIMUM_DEPENDENCIES + protocol::DOCUMENT_BACKBONE_BATCH_MAXIMUM_TARGET_SEGMENTS;
/// 📐️ Owner bytes of the largest declared batch: the credit page, its fixed owners (envelopes, dependency ids, target
/// segments), every declared byte, and one declared identifier per envelope for the document id the hub re-keys.
const ARTIFACT_SUBMIT_DECLARED_BATCH_BYTES: u64 = ARTIFACT_SUBMIT_PAGE_BYTES
    + (protocol::DOCUMENT_BACKBONE_BATCH_MAXIMUM_ENVELOPES * size_of::<protocol::MutationEnvelope>()
        + protocol::DOCUMENT_BACKBONE_BATCH_MAXIMUM_DEPENDENCIES * size_of::<protocol::MutationId>()
        + protocol::DOCUMENT_BACKBONE_BATCH_MAXIMUM_TARGET_SEGMENTS * size_of::<String>()
        + protocol::DOCUMENT_BACKBONE_BATCH_MAXIMUM_BYTES
        + protocol::DOCUMENT_BACKBONE_BATCH_MAXIMUM_ENVELOPES * protocol::DOCUMENT_BACKBONE_BATCH_MAXIMUM_IDENTIFIER_BYTES) as u64;
const ARTIFACT_SUBMIT_OPERATION_PAGES: u64 = ARTIFACT_SUBMIT_DECLARED_BATCH_BYTES.div_ceil(ARTIFACT_SUBMIT_PAGE_BYTES);
const ARTIFACT_SUBMIT_OPERATION_BYTES: u64 = ARTIFACT_SUBMIT_PAGE_BYTES * ARTIFACT_SUBMIT_OPERATION_PAGES;
/// 📐️ In-flight submit owners across every document: four declared-maximal batches at once; a fifth waits (`Unavailable`).
const ARTIFACT_SUBMIT_TOTAL_PAGES: u64 = ARTIFACT_SUBMIT_OPERATION_PAGES * 4;
const ARTIFACT_SUBMIT_TOTAL_BYTES: u64 = ARTIFACT_SUBMIT_PAGE_BYTES * ARTIFACT_SUBMIT_TOTAL_PAGES;
const ARTIFACT_SUBMIT_RETRY_MS: u64 = 1;
const ARTIFACT_SUBMIT_RETRY_LIMIT: u8 = 8;

#[derive(Clone, Copy)]
struct ArtifactSubmitAdmissionSlot {
    generation: u64,
    bytes: u64,
    items: usize,
    occupied: bool,
}

const EMPTY_ARTIFACT_SUBMIT_SLOT: ArtifactSubmitAdmissionSlot = ArtifactSubmitAdmissionSlot { generation: 0, bytes: 0, items: 0, occupied: false };

struct ArtifactSubmitAdmissionState {
    slots: [ArtifactSubmitAdmissionSlot; ARTIFACT_SUBMIT_OPERATION_ITEMS],
    bytes: u64,
    next_generation: u64,
}

static ARTIFACT_SUBMIT_ADMISSION: Mutex<ArtifactSubmitAdmissionState> = Mutex::new(ArtifactSubmitAdmissionState { slots: [EMPTY_ARTIFACT_SUBMIT_SLOT; ARTIFACT_SUBMIT_OPERATION_ITEMS], bytes: 0, next_generation: 1 });

struct ArtifactSubmitAdmission {
    slot: usize,
    generation: u64,
    bytes: u64,
    items: usize,
}

impl ArtifactSubmitAdmission {
    fn try_claim(items: usize, bytes: u64) -> Result<Self, DbError> {
        if items == 0 || items > ARTIFACT_SUBMIT_NESTED_ITEMS {
            return Err(DbError::LimitExceeded("artifact submit item credit"));
        }
        if bytes == 0 || bytes > ARTIFACT_SUBMIT_OPERATION_BYTES {
            return Err(DbError::LimitExceeded("artifact submit operation byte credit"));
        }
        let mut state = ARTIFACT_SUBMIT_ADMISSION.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let Some(slot) = state.slots.iter().position(|entry| !entry.occupied) else {
            return Err(DbError::Unavailable("artifact submit item capacity exhausted".to_string()));
        };
        if state.bytes.checked_add(bytes).is_none_or(|next| next > ARTIFACT_SUBMIT_TOTAL_BYTES) {
            return Err(DbError::Unavailable("artifact submit byte capacity exhausted".to_string()));
        }
        let generation = state.next_generation;
        state.next_generation = state.next_generation.checked_add(1).ok_or(DbError::LimitExceeded("artifact submit generation"))?;
        state.slots[slot] = ArtifactSubmitAdmissionSlot { generation, bytes, items, occupied: true };
        state.bytes += bytes;
        Ok(Self { slot, generation, bytes, items })
    }
}

impl Drop for ArtifactSubmitAdmission {
    fn drop(&mut self) {
        let mut state = ARTIFACT_SUBMIT_ADMISSION.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let entry = &mut state.slots[self.slot];
        if !entry.occupied || entry.generation != self.generation || entry.bytes != self.bytes || entry.items != self.items {
            return;
        }
        *entry = EMPTY_ARTIFACT_SUBMIT_SLOT;
        state.bytes = state.bytes.checked_sub(self.bytes).expect("artifact submit byte credit underflow");
    }
}

fn artifact_submit_credit(batch: &db_artifact::CommandBatch) -> Result<(usize, u64), DbError> {
    if batch.envelopes.is_empty() || batch.envelopes.len() > ARTIFACT_SUBMIT_BATCH_ITEMS {
        return Err(DbError::LimitExceeded("artifact submit batch item credit"));
    }
    let mut items = batch.envelopes.len();
    let mut bytes = ARTIFACT_SUBMIT_PAGE_BYTES;
    let envelope_owner_bytes = batch.envelopes.capacity().checked_mul(size_of::<protocol::MutationEnvelope>()).ok_or(DbError::LimitExceeded("artifact submit envelope owner bytes"))?;
    bytes = bytes.checked_add(envelope_owner_bytes as u64).ok_or(DbError::LimitExceeded("artifact submit envelope owner bytes"))?;
    for envelope in &batch.envelopes {
        items = items.checked_add(envelope.dependencies.len()).ok_or(DbError::LimitExceeded("artifact submit nested items"))?;
        if items > ARTIFACT_SUBMIT_NESTED_ITEMS {
            return Err(DbError::LimitExceeded("artifact submit nested item credit"));
        }
        let dependency_owner_bytes = envelope.dependencies.capacity().checked_mul(size_of::<protocol::MutationId>()).ok_or(DbError::LimitExceeded("artifact submit dependency owner bytes"))?;
        bytes = bytes
            .checked_add(envelope.mutation_id.0.capacity() as u64)
            .and_then(|value| value.checked_add(envelope.document_id.0.capacity() as u64))
            .and_then(|value| value.checked_add(envelope.actor.0.capacity() as u64))
            .and_then(|value| value.checked_add(dependency_owner_bytes as u64))
            .and_then(|value| value.checked_add(envelope.diff.schema.0.capacity() as u64))
            .and_then(|value| value.checked_add(envelope.diff.payload.capacity() as u64))
            .and_then(|value| value.checked_add(envelope.inverse.schema.0.capacity() as u64))
            .and_then(|value| value.checked_add(envelope.inverse.payload.capacity() as u64))
            .ok_or(DbError::LimitExceeded("artifact submit nested byte credit"))?;
        for dependency in &envelope.dependencies {
            bytes = bytes.checked_add(dependency.0.capacity() as u64).ok_or(DbError::LimitExceeded("artifact submit dependency byte credit"))?;
        }
        items = items.checked_add(envelope.target.len()).ok_or(DbError::LimitExceeded("artifact submit nested items"))?;
        if items > ARTIFACT_SUBMIT_NESTED_ITEMS {
            return Err(DbError::LimitExceeded("artifact submit nested item credit"));
        }
        let target_owner_bytes = envelope.target.capacity().checked_mul(size_of::<String>()).ok_or(DbError::LimitExceeded("artifact submit target owner bytes"))?;
        bytes = bytes
            .checked_add(target_owner_bytes as u64)
            .and_then(|value| value.checked_add(envelope.observed.as_ref().map_or(0, |observed| observed.0.capacity() as u64)))
            .ok_or(DbError::LimitExceeded("artifact submit target byte credit"))?;
        for segment in &envelope.target {
            bytes = bytes.checked_add(segment.capacity() as u64).ok_or(DbError::LimitExceeded("artifact submit target byte credit"))?;
        }
    }
    let pages = bytes.checked_add(ARTIFACT_SUBMIT_PAGE_BYTES - 1).ok_or(DbError::LimitExceeded("artifact submit page rounding"))? / ARTIFACT_SUBMIT_PAGE_BYTES;
    let admitted = pages.checked_mul(ARTIFACT_SUBMIT_PAGE_BYTES).ok_or(DbError::LimitExceeded("artifact submit page credit"))?;
    if admitted > ARTIFACT_SUBMIT_OPERATION_BYTES {
        return Err(DbError::LimitExceeded("artifact submit operation byte credit"));
    }
    Ok((items, admitted))
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SubmitProgress {
    Admitted,
    Scheduled,
    Waiting,
    Completed,
    Cancelled,
    Fault,
}

type ArtifactActorSubmitFuture = db_actor::AskFuture<db_artifact::ArtifactMessage, Result<db_artifact::CommandReceipt, DbError>>;
pub type ArtifactSubmitOutcome = Result<Result<CommandReceipt, DbError>, DbError>;

enum ArtifactSubmitWorkOwner {
    Request { batch: db_artifact::CommandBatch, options: db_artifact::SubmitOptions, submitted_at_ms: u64 },
    Actor(ArtifactActorSubmitFuture),
}

struct ArtifactSubmitState {
    pool: WorkerPool,
    authority: Mutex<Option<Arc<db_artifact::ArtifactAuthority>>>,
    document: protocol::ArtifactId,
    generation: u64,
    authority_generation: GenerationId,
    admission: Mutex<Option<ArtifactSubmitAdmission>>,
    work: Mutex<Option<ArtifactSubmitWorkOwner>>,
    completion: Mutex<Option<ArtifactSubmitOutcome>>,
    terminal_work: Mutex<Option<ArtifactSubmitWorkOwner>>,
    terminal_result: Mutex<Option<ArtifactSubmitOutcome>>,
    retry_job: Mutex<Option<(semio_framework_async::Job, u8)>>,
    terminal_job: Mutex<Option<(semio_framework_async::WorkerSubmitErrorKind, semio_framework_async::Job)>>,
    waker: Mutex<Option<std::task::Waker>>,
    retry_armed: std::sync::atomic::AtomicBool,
    retry_generation: std::sync::atomic::AtomicU64,
    scheduled: std::sync::atomic::AtomicBool,
    cancelled: std::sync::atomic::AtomicBool,
    abandoned: std::sync::atomic::AtomicBool,
    finished: std::sync::atomic::AtomicBool,
    progress: std::sync::atomic::AtomicU8,
}

pub struct SubmitFuture {
    state: Arc<ArtifactSubmitState>,
    resolved: bool,
}

pub struct ArtifactSubmitTerminalJob {
    state: Arc<ArtifactSubmitState>,
    owner: Option<(semio_framework_async::WorkerSubmitErrorKind, semio_framework_async::Job)>,
}

pub struct ArtifactSubmitTerminalWork {
    state: Arc<ArtifactSubmitState>,
    owner: Option<ArtifactSubmitWorkOwner>,
}

struct ArtifactSubmitWake {
    state: std::sync::Weak<ArtifactSubmitState>,
    generation: u64,
}

impl std::task::Wake for ArtifactSubmitWake {
    fn wake(self: Arc<Self>) {
        self.wake_by_ref();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        if let Some(state) = self.state.upgrade() {
            if self.generation == state.generation {
                state.schedule();
            }
        }
    }
}

impl ArtifactSubmitState {
    fn set_progress(&self, progress: SubmitProgress) {
        self.progress.store(progress as u8, std::sync::atomic::Ordering::Release);
    }

    fn wake_waiter(&self) {
        if let Some(waker) = self.waker.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
            waker.wake();
        }
    }

    fn finish(&self) {
        if !self.finished.swap(true, std::sync::atomic::Ordering::AcqRel) {
            self.admission.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
            self.authority.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
        }
    }

    fn authority(&self) -> Option<Arc<db_artifact::ArtifactAuthority>> {
        self.authority.lock().unwrap_or_else(std::sync::PoisonError::into_inner).clone()
    }

    fn terminal_is_empty(&self) -> bool {
        self.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none()
            && self.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none()
            && self.terminal_work.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none()
            && self.terminal_result.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none()
            && self.work.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none()
            && self.completion.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none()
    }

    fn finish_if_terminal_empty(&self) {
        if self.terminal_is_empty() && !self.scheduled.load(std::sync::atomic::Ordering::Acquire) && !self.retry_armed.load(std::sync::atomic::Ordering::Acquire) {
            self.finish();
        }
    }

    fn complete(&self, result: ArtifactSubmitOutcome, progress: SubmitProgress) {
        self.set_progress(progress);
        if self.abandoned.load(std::sync::atomic::Ordering::Acquire) {
            *self.terminal_result.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(result);
        } else {
            *self.completion.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(result);
            self.wake_waiter();
        }
    }

    fn terminalize_work(&self, result: ArtifactSubmitOutcome, progress: SubmitProgress) {
        if let Some(work) = self.work.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
            *self.terminal_work.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(work);
        }
        self.complete(result, progress);
    }

    fn schedule(self: &Arc<Self>) {
        use std::sync::atomic::Ordering;
        if self.finished.load(Ordering::Acquire) || self.scheduled.compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire).is_err() {
            return;
        }
        self.set_progress(SubmitProgress::Scheduled);
        let state = self.clone();
        let generation = self.generation;
        self.submit_exact(Box::new(move || state.drive_one(generation)), 0);
    }

    fn submit_exact(self: &Arc<Self>, job: semio_framework_async::Job, attempt: u8) {
        match self.pool.try_submit(Lane::Io, job) {
            Ok(()) => {}
            Err(error) => match worker_submit_retry_attempt(error.kind(), attempt, ARTIFACT_SUBMIT_RETRY_LIMIT) {
                Some(next) => {
                    *self.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some((error.into_job(), next));
                    self.arm_retry();
                }
                None => {
                    let kind = error.kind();
                    let job = error.into_job();
                    self.scheduled.store(false, std::sync::atomic::Ordering::Release);
                    if let Some(work) = self.work.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
                        *self.terminal_work.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(work);
                    }
                    *self.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some((kind, job));
                    self.complete(Err(DbError::Unavailable(format!("artifact submit WorkerPool submission failed: {kind:?}"))), SubmitProgress::Fault);
                }
            },
        }
    }

    fn arm_retry(self: &Arc<Self>) {
        use std::sync::atomic::Ordering;
        if self.retry_armed.compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire).is_err() {
            return;
        }
        let generation = match self.retry_generation.try_update(Ordering::AcqRel, Ordering::Acquire, |generation| generation.checked_add(1).filter(|next| *next != 0)) {
            Ok(previous) => match previous.checked_add(1) {
                Some(generation) => generation,
                None => {
                    self.terminalize_retry_authority("artifact submit retry generation exhausted");
                    return;
                }
            },
            Err(_) => {
                self.terminalize_retry_authority("artifact submit retry generation exhausted");
                return;
            }
        };
        let Some(deadline) = self.pool.now_ms().checked_add(ARTIFACT_SUBMIT_RETRY_MS) else {
            self.terminalize_retry_authority("artifact submit retry deadline exhausted");
            return;
        };
        let state = self.clone();
        self.pool.callback_at(deadline, move || {
            if generation != state.retry_generation.load(Ordering::Acquire) {
                return;
            }
            state.retry_armed.store(false, Ordering::Release);
            let retry = state.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
            if let Some((job, attempt)) = retry {
                if state.cancelled.load(Ordering::Acquire) {
                    drop(job);
                    state.scheduled.store(false, Ordering::Release);
                    state.terminalize_work(Err(DbError::Closed), SubmitProgress::Cancelled);
                } else {
                    state.submit_exact(job, attempt);
                }
            }
        });
    }

    fn terminalize_retry_authority(&self, detail: &'static str) {
        self.retry_armed.store(false, std::sync::atomic::Ordering::Release);
        self.scheduled.store(false, std::sync::atomic::Ordering::Release);
        let retained = self.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
        if let Some((job, attempt)) = retained {
            let mut terminal = self.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            if terminal.is_none() {
                *terminal = Some((semio_framework_async::WorkerSubmitErrorKind::Saturated, job));
            } else {
                drop(terminal);
                *self.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some((job, attempt));
            }
        }
        self.terminalize_work(Err(DbError::Unavailable(detail.to_string())), SubmitProgress::Fault);
    }

    fn drive_one(self: Arc<Self>, generation: u64) {
        use std::future::Future as _;
        use std::sync::atomic::Ordering;

        if generation != self.generation {
            return;
        }
        let Some(authority) = self.authority() else {
            self.scheduled.store(false, Ordering::Release);
            self.terminalize_work(Err(DbError::Closed), SubmitProgress::Cancelled);
            return;
        };
        if authority.generation() != self.authority_generation {
            self.scheduled.store(false, Ordering::Release);
            self.terminalize_work(Err(DbError::StaleGeneration { expected: authority.generation(), actual: self.authority_generation }), SubmitProgress::Fault);
            return;
        }
        self.scheduled.store(false, Ordering::Release);
        if self.cancelled.load(Ordering::Acquire) {
            self.terminalize_work(Err(DbError::Closed), SubmitProgress::Cancelled);
            return;
        }

        let mut work = self.work.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if matches!(work.as_ref(), Some(ArtifactSubmitWorkOwner::Request { .. })) {
            let Some(ArtifactSubmitWorkOwner::Request { batch, options, submitted_at_ms }) = work.take() else {
                return;
            };
            *work = Some(ArtifactSubmitWorkOwner::Actor(authority.submit_retained(batch, options, submitted_at_ms)));
            drop(work);
            self.schedule();
            return;
        }

        let Some(ArtifactSubmitWorkOwner::Actor(future)) = work.as_mut() else {
            return;
        };
        let waker = std::task::Waker::from(Arc::new(ArtifactSubmitWake { state: Arc::downgrade(&self), generation }));
        let mut context = std::task::Context::from_waker(&waker);
        match std::pin::Pin::new(future).poll(&mut context) {
            std::task::Poll::Pending => {
                self.set_progress(SubmitProgress::Waiting);
            }
            std::task::Poll::Ready(result) => {
                work.take();
                drop(work);
                let result = result.map(|inner| inner.map(|receipt| to_engine_receipt(receipt, self.document.clone())));
                if self.cancelled.load(Ordering::Acquire) {
                    *self.terminal_result.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(result);
                    self.complete(Err(DbError::Closed), SubmitProgress::Cancelled);
                } else {
                    self.complete(result, SubmitProgress::Completed);
                }
            }
        }
    }

    fn close_one(&self) -> bool {
        if let Some((_, job)) = self.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
            drop(job);
            return true;
        }
        if let Some((job, _)) = self.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
            drop(job);
            return true;
        }
        if let Some(work) = self.terminal_work.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
            drop(work);
            return true;
        }
        if let Some(result) = self.terminal_result.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
            drop(result);
            return true;
        }
        false
    }
}

impl SubmitFuture {
    fn submit(handle: &ArtifactHandle, batch: db_artifact::CommandBatch, options: db_artifact::SubmitOptions) -> Self {
        let credit = artifact_submit_credit(&batch).and_then(|(items, bytes)| ArtifactSubmitAdmission::try_claim(items, bytes));
        let admission_error = credit.as_ref().err().cloned();
        let generation = credit.as_ref().map_or(0, |admission| admission.generation);
        let request = ArtifactSubmitWorkOwner::Request { batch, options, submitted_at_ms: handle.pool.now_ms() };
        let (work, terminal_work) = if generation == 0 { (None, Some(request)) } else { (Some(request), None) };
        let state = Arc::new(ArtifactSubmitState {
            pool: handle.pool.as_ref().clone(),
            authority: Mutex::new(Some(handle.authority.clone())),
            document: handle.document.clone(),
            generation,
            authority_generation: handle.authority.generation(),
            admission: Mutex::new(credit.ok()),
            work: Mutex::new(work),
            completion: Mutex::new(None),
            terminal_work: Mutex::new(terminal_work),
            terminal_result: Mutex::new(None),
            retry_job: Mutex::new(None),
            terminal_job: Mutex::new(None),
            waker: Mutex::new(None),
            retry_armed: std::sync::atomic::AtomicBool::new(false),
            retry_generation: std::sync::atomic::AtomicU64::new(1),
            scheduled: std::sync::atomic::AtomicBool::new(false),
            cancelled: std::sync::atomic::AtomicBool::new(false),
            abandoned: std::sync::atomic::AtomicBool::new(false),
            finished: std::sync::atomic::AtomicBool::new(false),
            progress: std::sync::atomic::AtomicU8::new(if generation == 0 { SubmitProgress::Fault as u8 } else { SubmitProgress::Admitted as u8 }),
        });
        if generation == 0 {
            *state.completion.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Err(admission_error.unwrap_or_else(|| DbError::Unavailable("artifact submit admission exhausted".to_string()))));
        } else {
            state.schedule();
        }
        Self { state, resolved: false }
    }

    pub fn generation(&self) -> u64 {
        self.state.generation
    }

    pub fn progress(&self) -> SubmitProgress {
        match self.state.progress.load(std::sync::atomic::Ordering::Acquire) {
            0 => SubmitProgress::Admitted,
            1 => SubmitProgress::Scheduled,
            2 => SubmitProgress::Waiting,
            3 => SubmitProgress::Completed,
            4 => SubmitProgress::Cancelled,
            _ => SubmitProgress::Fault,
        }
    }

    pub fn cancel(&self) {
        if matches!(self.progress(), SubmitProgress::Completed | SubmitProgress::Cancelled | SubmitProgress::Fault) {
            return;
        }
        self.state.cancelled.store(true, std::sync::atomic::Ordering::Release);
        self.state.schedule();
    }

    pub fn take_terminal_job(&self) -> Option<ArtifactSubmitTerminalJob> {
        self.state.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take().map(|owner| ArtifactSubmitTerminalJob { state: self.state.clone(), owner: Some(owner) })
    }

    pub fn take_terminal_work(&self) -> Option<ArtifactSubmitTerminalWork> {
        self.state.terminal_work.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take().map(|owner| ArtifactSubmitTerminalWork { state: self.state.clone(), owner: Some(owner) })
    }

    pub fn take_terminal_result(&self) -> Option<ArtifactSubmitOutcome> {
        let result = self.state.terminal_result.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
        if result.is_some() {
            self.state.finish_if_terminal_empty();
        }
        result
    }

    pub fn take_actor_terminal_job(&self) -> Option<db_artifact::ArtifactRunnerTerminalJob> {
        self.state.authority().and_then(|authority| authority.take_terminal_job())
    }

    pub fn close_step(&self) -> bool {
        let progressed = self.state.close_one() || self.state.authority().is_some_and(|authority| authority.close_step());
        self.state.finish_if_terminal_empty();
        progressed
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.state.terminal_is_empty() && self.state.authority().is_none_or(|authority| authority.terminal_is_empty())
    }
}

impl Future for SubmitFuture {
    type Output = ArtifactSubmitOutcome;

    fn poll(mut self: std::pin::Pin<&mut Self>, context: &mut std::task::Context<'_>) -> std::task::Poll<Self::Output> {
        let result = self.state.completion.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
        if let Some(result) = result {
            self.resolved = true;
            self.state.finish_if_terminal_empty();
            return std::task::Poll::Ready(result);
        }
        *self.state.waker.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(context.waker().clone());
        let result = self.state.completion.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
        if let Some(result) = result {
            self.resolved = true;
            self.state.finish_if_terminal_empty();
            return std::task::Poll::Ready(result);
        }
        std::task::Poll::Pending
    }
}

impl Drop for SubmitFuture {
    fn drop(&mut self) {
        if !self.resolved {
            self.state.abandoned.store(true, std::sync::atomic::Ordering::Release);
            self.state.cancelled.store(true, std::sync::atomic::Ordering::Release);
            self.state.schedule();
        }
        self.state.close_one();
        self.state.finish_if_terminal_empty();
    }
}

impl ArtifactSubmitTerminalJob {
    pub fn reason(&self) -> semio_framework_async::WorkerSubmitErrorKind {
        self.owner.as_ref().expect("terminal artifact submit job already resolved").0
    }

    pub fn resume(mut self) {
        let (_, job) = self.owner.take().expect("terminal artifact submit job already resolved");
        if self.state.work.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none() {
            let work = self.state.terminal_work.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
            *self.state.work.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = work;
        }
        if let Some(result) = self.state.completion.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
            *self.state.terminal_result.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(result);
        }
        self.state.cancelled.store(false, std::sync::atomic::Ordering::Release);
        self.state.set_progress(SubmitProgress::Scheduled);
        self.state.scheduled.store(true, std::sync::atomic::Ordering::Release);
        self.state.submit_exact(job, 0);
    }

    pub fn close(mut self) {
        let (_, job) = self.owner.take().expect("terminal artifact submit job already resolved");
        drop(job);
        self.state.finish_if_terminal_empty();
    }
}

impl Drop for ArtifactSubmitTerminalJob {
    fn drop(&mut self) {
        if let Some(owner) = self.owner.take() {
            *self.state.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(owner);
        }
    }
}

impl ArtifactSubmitTerminalWork {
    pub fn resume(mut self) -> Result<(), Self> {
        if self.state.generation == 0 {
            return Err(self);
        }
        let owner = self.owner.take().expect("terminal artifact submit work already resolved");
        *self.state.work.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(owner);
        if let Some(result) = self.state.completion.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
            *self.state.terminal_result.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(result);
        }
        self.state.cancelled.store(false, std::sync::atomic::Ordering::Release);
        self.state.set_progress(SubmitProgress::Admitted);
        if self.state.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none() {
            self.state.schedule();
        }
        Ok(())
    }

    pub fn close(mut self) {
        drop(self.owner.take().expect("terminal artifact submit work already resolved"));
        self.state.finish_if_terminal_empty();
    }
}

impl Drop for ArtifactSubmitTerminalWork {
    fn drop(&mut self) {
        if let Some(owner) = self.owner.take() {
            *self.state.terminal_work.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(owner);
        }
    }
}

const ARTIFACT_HISTORY_OPERATION_SLOTS: usize = 8;
const ARTIFACT_HISTORY_PAGE_BYTES: u64 = 16 * 1024;
const ARTIFACT_HISTORY_OPERATION_PAGES: u64 = 2_048;
const ARTIFACT_HISTORY_OPERATION_BYTES: u64 = ARTIFACT_HISTORY_PAGE_BYTES * ARTIFACT_HISTORY_OPERATION_PAGES;
const ARTIFACT_HISTORY_TOTAL_BYTES: u64 = ARTIFACT_HISTORY_OPERATION_BYTES * ARTIFACT_HISTORY_OPERATION_SLOTS as u64;
const ARTIFACT_HISTORY_OPERATION_ITEMS: usize = 20_481;

#[derive(Clone, Copy)]
struct ArtifactHistoryAdmissionSlot {
    generation: u64,
    bytes: u64,
    items: usize,
    occupied: bool,
}

const EMPTY_ARTIFACT_HISTORY_SLOT: ArtifactHistoryAdmissionSlot = ArtifactHistoryAdmissionSlot { generation: 0, bytes: 0, items: 0, occupied: false };

struct ArtifactHistoryAdmissionState {
    slots: [ArtifactHistoryAdmissionSlot; ARTIFACT_HISTORY_OPERATION_SLOTS],
    bytes: u64,
    next_generation: u64,
}

static ARTIFACT_HISTORY_ADMISSION: Mutex<ArtifactHistoryAdmissionState> = Mutex::new(ArtifactHistoryAdmissionState { slots: [EMPTY_ARTIFACT_HISTORY_SLOT; ARTIFACT_HISTORY_OPERATION_SLOTS], bytes: 0, next_generation: 1 });

struct ArtifactHistoryAdmission {
    slot: usize,
    generation: u64,
    reservation: Option<db_artifact::HistoryReplayReservation>,
}

enum ArtifactHistoryAdmissionError {
    Rejected(DbError),
    Construction { admission: ArtifactHistoryAdmission, fault: db_artifact::HistoryReplayReservationConstructionFault },
}

impl std::fmt::Debug for ArtifactHistoryAdmissionError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Rejected(error) => formatter.debug_tuple("Rejected").field(error).finish(),
            Self::Construction { fault, .. } => formatter.debug_struct("Construction").field("fault", fault).finish(),
        }
    }
}

impl ArtifactHistoryAdmission {
    fn try_claim() -> Result<Self, ArtifactHistoryAdmissionError> {
        let (slot, generation) = {
            let mut state = ARTIFACT_HISTORY_ADMISSION.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            let Some(slot) = state.slots.iter().position(|entry| !entry.occupied) else {
                return Err(ArtifactHistoryAdmissionError::Rejected(DbError::Unavailable("artifact history item capacity exhausted".to_string())));
            };
            let Some(next_bytes) = state.bytes.checked_add(ARTIFACT_HISTORY_OPERATION_BYTES) else {
                return Err(ArtifactHistoryAdmissionError::Rejected(DbError::LimitExceeded("artifact history aggregate bytes")));
            };
            if next_bytes > ARTIFACT_HISTORY_TOTAL_BYTES {
                return Err(ArtifactHistoryAdmissionError::Rejected(DbError::Unavailable("artifact history byte capacity exhausted".to_string())));
            }
            let generation = state.next_generation;
            let Some(next_generation) = state.next_generation.checked_add(1) else {
                return Err(ArtifactHistoryAdmissionError::Rejected(DbError::LimitExceeded("artifact history generation")));
            };
            state.next_generation = next_generation;
            state.slots[slot] = ArtifactHistoryAdmissionSlot { generation, bytes: ARTIFACT_HISTORY_OPERATION_BYTES, items: ARTIFACT_HISTORY_OPERATION_ITEMS, occupied: true };
            state.bytes = next_bytes;
            (slot, generation)
        };
        let mut claim = Self { slot, generation, reservation: None };
        match db_artifact::HistoryReplayReservation::try_new() {
            Ok(reservation) => {
                claim.reservation = Some(reservation);
                Ok(claim)
            }
            Err(fault) => Err(ArtifactHistoryAdmissionError::Construction { admission: claim, fault }),
        }
    }

    fn take_reservation(&mut self) -> Option<db_artifact::HistoryReplayReservation> {
        self.reservation.take()
    }

    fn begin_reservation_close(&mut self) -> Option<db_artifact::HistoryReplayReservationCloseCursor> {
        self.reservation.take().map(db_artifact::HistoryReplayReservationCloseCursor::new)
    }

    fn restore_reservation(&mut self, reservation: db_artifact::HistoryReplayReservation) {
        assert!(self.reservation.is_none(), "artifact history reservation restore slot was occupied");
        self.reservation = Some(reservation);
    }
}

impl Drop for ArtifactHistoryAdmission {
    fn drop(&mut self) {
        let live = self.reservation.take().is_some();
        {
            let mut state = ARTIFACT_HISTORY_ADMISSION.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            let entry = &mut state.slots[self.slot];
            if entry.occupied && entry.generation == self.generation && entry.bytes == ARTIFACT_HISTORY_OPERATION_BYTES && entry.items == ARTIFACT_HISTORY_OPERATION_ITEMS {
                *entry = EMPTY_ARTIFACT_HISTORY_SLOT;
                state.bytes = state.bytes.checked_sub(ARTIFACT_HISTORY_OPERATION_BYTES).expect("artifact history byte credit underflow");
            }
        }
        assert!(!live || std::thread::panicking(), "artifact history admission dropped a live replay reservation");
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HistoryProgress {
    Admitted,
    Scheduled,
    Waiting,
    Mapping,
    Completed,
    Cancelled,
    Fault,
}

type ArtifactActorHistoryFuture = db_actor::AskFuture<db_artifact::ArtifactMessage, Result<db_artifact::ArtifactHistoryView, DbError>>;
pub type ArtifactHistoryOutcome = Result<HistoryView, DbError>;

enum ArtifactHistoryWorkOwner {
    Request,
    Actor(ArtifactActorHistoryFuture),
}

struct ArtifactHistoryState {
    pool: WorkerPool,
    authority: Arc<db_artifact::ArtifactAuthority>,
    generation: u64,
    authority_generation: GenerationId,
    admission: Mutex<Option<ArtifactHistoryAdmission>>,
    work: Mutex<Option<ArtifactHistoryWorkOwner>>,
    completion: Mutex<Option<ArtifactHistoryOutcome>>,
    terminal_work: Mutex<Option<ArtifactHistoryWorkOwner>>,
    terminal_result: Mutex<Option<ArtifactHistoryOutcome>>,
    terminal_reservation: Mutex<Option<db_artifact::HistoryReplayReservationCloseCursor>>,
    reservation_checked_out: std::sync::atomic::AtomicBool,
    terminal_construction: Mutex<Option<db_artifact::HistoryReplayReservationConstructionFault>>,
    construction_checked_out: std::sync::atomic::AtomicBool,
    retry_job: Mutex<Option<(semio_framework_async::Job, u8)>>,
    terminal_job: Mutex<Option<(semio_framework_async::WorkerSubmitErrorKind, semio_framework_async::Job)>>,
    waker: Mutex<Option<std::task::Waker>>,
    retry_armed: std::sync::atomic::AtomicBool,
    retry_generation: std::sync::atomic::AtomicU64,
    scheduled: std::sync::atomic::AtomicBool,
    cancelled: Arc<std::sync::atomic::AtomicBool>,
    abandoned: std::sync::atomic::AtomicBool,
    finished: std::sync::atomic::AtomicBool,
    progress: std::sync::atomic::AtomicU8,
    #[cfg(test)]
    controlled_completion_hook: Mutex<Option<Box<dyn FnOnce(ArtifactHistoryOutcome, HistoryProgress) + Send>>>,
    #[cfg(test)]
    controlled_publication_before_waker_hook: Mutex<Option<semio_framework_async::Job>>,
}

pub struct HistoryFuture {
    state: Arc<ArtifactHistoryState>,
    resolved: bool,
}

pub struct ArtifactHistoryTerminalHandle {
    state: Arc<ArtifactHistoryState>,
}

pub struct ArtifactHistoryTerminalJob {
    state: Arc<ArtifactHistoryState>,
    owner: Option<(semio_framework_async::WorkerSubmitErrorKind, semio_framework_async::Job)>,
}

pub struct ArtifactHistoryTerminalWork {
    state: Arc<ArtifactHistoryState>,
    owner: Option<ArtifactHistoryWorkOwner>,
}

pub struct ArtifactHistoryTerminalReservation {
    state: Arc<ArtifactHistoryState>,
    owner: Option<db_artifact::HistoryReplayReservationCloseCursor>,
}

pub struct ArtifactHistoryTerminalConstructionFault {
    state: Arc<ArtifactHistoryState>,
    owner: Option<db_artifact::HistoryReplayReservationConstructionFault>,
}

struct ArtifactHistoryWake {
    state: std::sync::Weak<ArtifactHistoryState>,
    generation: u64,
}

fn artifact_history_registry() -> &'static Mutex<[Option<Arc<ArtifactHistoryState>>; ARTIFACT_HISTORY_OPERATION_SLOTS]> {
    static REGISTRY: std::sync::OnceLock<Mutex<[Option<Arc<ArtifactHistoryState>>; ARTIFACT_HISTORY_OPERATION_SLOTS]>> = std::sync::OnceLock::new();
    REGISTRY.get_or_init(|| Mutex::new(std::array::from_fn(|_| None)))
}

fn register_artifact_history(state: &Arc<ArtifactHistoryState>) {
    if state.generation == 0 {
        return;
    }
    let mut registry = artifact_history_registry().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
    if registry.iter().any(|slot| slot.as_ref().is_some_and(|registered| registered.generation == state.generation)) {
        return;
    }
    if let Some(slot) = registry.iter_mut().find(|slot| slot.is_none()) {
        *slot = Some(state.clone());
    }
}

fn unregister_artifact_history(generation: u64) {
    let mut registry = artifact_history_registry().lock().unwrap_or_else(std::sync::PoisonError::into_inner);
    if let Some(slot) = registry.iter_mut().find(|slot| slot.as_ref().is_some_and(|state| state.generation == generation)) {
        *slot = None;
    }
}

impl std::task::Wake for ArtifactHistoryWake {
    fn wake(self: Arc<Self>) {
        self.wake_by_ref();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        if let Some(state) = self.state.upgrade() {
            if self.generation == state.generation {
                state.schedule();
            }
        }
    }
}

impl ArtifactHistoryState {
    fn set_progress(&self, progress: HistoryProgress) {
        self.progress.store(progress as u8, std::sync::atomic::Ordering::Release);
    }

    fn wake_waiter(&self) {
        let waker = self.waker.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
        if let Some(waker) = waker {
            waker.wake();
        }
    }

    fn take_terminal_reservation(self: &Arc<Self>) -> Option<ArtifactHistoryTerminalReservation> {
        use std::sync::atomic::Ordering;
        if self.reservation_checked_out.compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire).is_err() {
            return None;
        }
        let owner = self.terminal_reservation.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
        if owner.is_none() {
            self.reservation_checked_out.store(false, Ordering::Release);
            return None;
        }
        Some(ArtifactHistoryTerminalReservation { state: self.clone(), owner })
    }

    fn take_terminal_construction_fault(self: &Arc<Self>) -> Option<ArtifactHistoryTerminalConstructionFault> {
        use std::sync::atomic::Ordering;
        if self.construction_checked_out.compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire).is_err() {
            return None;
        }
        let owner = self.terminal_construction.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
        if owner.is_none() {
            self.construction_checked_out.store(false, Ordering::Release);
            return None;
        }
        Some(ArtifactHistoryTerminalConstructionFault { state: self.clone(), owner })
    }

    fn terminal_roots_are_empty(&self) -> bool {
        self.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none()
            && self.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none()
            && self.terminal_work.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none()
            && self.terminal_result.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none()
            && self.terminal_reservation.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none()
            && !self.reservation_checked_out.load(std::sync::atomic::Ordering::Acquire)
            && self.terminal_construction.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none()
            && !self.construction_checked_out.load(std::sync::atomic::Ordering::Acquire)
            && self.work.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none()
            && self.completion.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none()
    }

    fn terminal_is_empty(&self) -> bool {
        self.finished.load(std::sync::atomic::Ordering::Acquire)
            && self.admission.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_none()
            && self.terminal_roots_are_empty()
            && !self.scheduled.load(std::sync::atomic::Ordering::Acquire)
            && !self.retry_armed.load(std::sync::atomic::Ordering::Acquire)
    }

    fn finish_if_terminal_empty(&self) -> bool {
        use std::sync::atomic::Ordering;
        if !self.terminal_roots_are_empty() || self.scheduled.load(Ordering::Acquire) || self.retry_armed.load(Ordering::Acquire) {
            return false;
        }
        let mut admission = self.admission.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if self.finished.load(Ordering::Acquire) {
            return false;
        }
        let owner = admission.take();
        assert!(owner.as_ref().is_none_or(|owner| owner.reservation.is_none()), "artifact history admission finished before reservation retirement");
        drop(owner);
        unregister_artifact_history(self.generation);
        self.finished.store(true, Ordering::Release);
        true
    }

    fn begin_unhanded_reservation_close(&self) {
        if self.terminal_reservation.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_some() || self.reservation_checked_out.load(std::sync::atomic::Ordering::Acquire) {
            return;
        }
        let cursor = self.admission.lock().unwrap_or_else(std::sync::PoisonError::into_inner).as_mut().and_then(ArtifactHistoryAdmission::begin_reservation_close);
        if let Some(cursor) = cursor {
            *self.terminal_reservation.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(cursor);
        }
    }

    fn resume_unhanded_reservation(&self) -> bool {
        if self.reservation_checked_out.load(std::sync::atomic::Ordering::Acquire) {
            return false;
        }
        let mut terminal = self.terminal_reservation.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        let Some(cursor) = terminal.as_mut() else {
            return self.admission.lock().unwrap_or_else(std::sync::PoisonError::into_inner).as_ref().is_some_and(|owner| owner.reservation.is_some());
        };
        let mut admission = self.admission.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if admission.as_ref().is_none_or(|owner| owner.reservation.is_some()) {
            return false;
        }
        let Some(reservation) = cursor.resume() else {
            return false;
        };
        let admission = admission.as_mut().expect("artifact history reservation admission disappeared after preflight");
        admission.restore_reservation(reservation);
        terminal.take();
        true
    }

    fn complete(&self, result: ArtifactHistoryOutcome, progress: HistoryProgress) {
        self.set_progress(progress);
        #[cfg(test)]
        {
            let hook = self.controlled_completion_hook.lock().unwrap().take();
            if let Some(hook) = hook {
                hook(result, progress);
                return;
            }
        }
        let mut completion = self.completion.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if self.abandoned.load(std::sync::atomic::Ordering::Acquire) {
            drop(completion);
            *self.terminal_result.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(result);
        } else {
            *completion = Some(result);
            drop(completion);
            self.wake_waiter();
        }
    }

    fn terminalize_work(&self, result: ArtifactHistoryOutcome, progress: HistoryProgress) {
        if let Some(work) = self.work.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
            if matches!(&work, ArtifactHistoryWorkOwner::Request) {
                self.begin_unhanded_reservation_close();
            }
            *self.terminal_work.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(work);
        }
        self.complete(result, progress);
    }

    fn terminalize_unhanded_request(&self, result: ArtifactHistoryOutcome, progress: HistoryProgress) -> bool {
        let mut work = self.work.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if !work.as_ref().is_some_and(|owner| matches!(owner, ArtifactHistoryWorkOwner::Request)) {
            return false;
        }
        let request = work.take().expect("artifact history request disappeared after retained preflight");
        drop(work);
        self.begin_unhanded_reservation_close();
        *self.terminal_work.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(request);
        self.complete(result, progress);
        true
    }

    fn schedule(self: &Arc<Self>) {
        use std::sync::atomic::Ordering;
        if self.finished.load(Ordering::Acquire)
            || self.terminal_construction.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_some()
            || self.construction_checked_out.load(Ordering::Acquire)
            || self.scheduled.compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire).is_err()
        {
            return;
        }
        self.set_progress(HistoryProgress::Scheduled);
        let state = self.clone();
        let generation = self.generation;
        self.submit_exact(Box::new(move || state.drive_one(generation)), 0);
    }

    fn submit_exact(self: &Arc<Self>, job: semio_framework_async::Job, attempt: u8) {
        match self.pool.try_submit(Lane::Io, job) {
            Ok(()) => {}
            Err(error) => match worker_submit_retry_attempt(error.kind(), attempt, ARTIFACT_SUBMIT_RETRY_LIMIT) {
                Some(next) => {
                    *self.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some((error.into_job(), next));
                    self.arm_retry();
                }
                None => {
                    let kind = error.kind();
                    let job = error.into_job();
                    self.scheduled.store(false, std::sync::atomic::Ordering::Release);
                    *self.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some((kind, job));
                    self.terminalize_work(Err(DbError::Unavailable(format!("artifact history WorkerPool submission failed: {kind:?}"))), HistoryProgress::Fault);
                }
            },
        }
    }

    fn arm_retry(self: &Arc<Self>) {
        use std::sync::atomic::Ordering;
        if self.retry_armed.compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire).is_err() {
            return;
        }
        let generation = match self.retry_generation.try_update(Ordering::AcqRel, Ordering::Acquire, |generation| generation.checked_add(1).filter(|next| *next != 0)) {
            Ok(previous) => match previous.checked_add(1) {
                Some(generation) => generation,
                None => {
                    self.terminalize_retry_authority("artifact history retry generation exhausted");
                    return;
                }
            },
            Err(_) => {
                self.terminalize_retry_authority("artifact history retry generation exhausted");
                return;
            }
        };
        let Some(deadline) = self.pool.now_ms().checked_add(ARTIFACT_SUBMIT_RETRY_MS) else {
            self.terminalize_retry_authority("artifact history retry deadline exhausted");
            return;
        };
        let state = self.clone();
        self.pool.callback_at(deadline, move || {
            if generation != state.retry_generation.load(Ordering::Acquire) {
                return;
            }
            state.retry_armed.store(false, Ordering::Release);
            let retry = state.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
            if let Some((job, attempt)) = retry {
                if state.cancelled.load(Ordering::Acquire) {
                    state.scheduled.store(false, Ordering::Release);
                    *state.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some((semio_framework_async::WorkerSubmitErrorKind::Saturated, job));
                    state.terminalize_work(Err(DbError::Closed), HistoryProgress::Cancelled);
                } else {
                    state.submit_exact(job, attempt);
                }
            }
        });
    }

    fn terminalize_retry_authority(&self, detail: &'static str) {
        self.retry_armed.store(false, std::sync::atomic::Ordering::Release);
        self.scheduled.store(false, std::sync::atomic::Ordering::Release);
        let retained = self.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
        if let Some((job, attempt)) = retained {
            let mut terminal = self.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            if terminal.is_none() {
                *terminal = Some((semio_framework_async::WorkerSubmitErrorKind::Saturated, job));
            } else {
                drop(terminal);
                *self.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some((job, attempt));
            }
        }
        self.terminalize_work(Err(DbError::Unavailable(detail.to_string())), HistoryProgress::Fault);
    }

    fn drive_one(self: Arc<Self>, generation: u64) {
        use std::future::Future as _;
        use std::sync::atomic::Ordering;

        if generation != self.generation {
            return;
        }
        self.scheduled.store(false, Ordering::Release);
        if self.authority.generation() != self.authority_generation {
            self.cancelled.store(true, Ordering::Release);
            let actor_active = self.work.lock().unwrap_or_else(std::sync::PoisonError::into_inner).as_ref().is_some_and(|owner| matches!(owner, ArtifactHistoryWorkOwner::Actor(_)));
            if !actor_active {
                self.terminalize_work(Err(DbError::StaleGeneration { expected: self.authority.generation(), actual: self.authority_generation }), HistoryProgress::Fault);
                return;
            }
        }
        if self.cancelled.load(Ordering::Acquire) {
            let actor_active = self.work.lock().unwrap_or_else(std::sync::PoisonError::into_inner).as_ref().is_some_and(|owner| matches!(owner, ArtifactHistoryWorkOwner::Actor(_)));
            if !actor_active {
                self.terminalize_work(Err(DbError::Closed), HistoryProgress::Cancelled);
                return;
            }
        }

        let mut work = self.work.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        match work.as_mut() {
            Some(ArtifactHistoryWorkOwner::Request) => {
                let reservation = self.admission.lock().unwrap_or_else(std::sync::PoisonError::into_inner).as_mut().and_then(ArtifactHistoryAdmission::take_reservation);
                let Some(reservation) = reservation else {
                    drop(work);
                    self.terminalize_work(Err(DbError::Unavailable("artifact history fixed reservation owner is missing".to_string())), HistoryProgress::Fault);
                    return;
                };
                *work = Some(ArtifactHistoryWorkOwner::Actor(self.authority.history_retained(self.generation, self.cancelled.clone(), reservation)));
                drop(work);
                self.schedule();
            }
            Some(ArtifactHistoryWorkOwner::Actor(future)) => {
                let waker = std::task::Waker::from(Arc::new(ArtifactHistoryWake { state: Arc::downgrade(&self), generation }));
                let mut context = std::task::Context::from_waker(&waker);
                match std::pin::Pin::new(future).poll(&mut context) {
                    std::task::Poll::Pending => self.set_progress(HistoryProgress::Waiting),
                    std::task::Poll::Ready(Ok(Ok(view))) => {
                        work.take();
                        drop(work);
                        let admission = self.admission.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
                        match admission {
                            Some(admission) => self.complete(Ok(HistoryView::new(view, Some(admission), self.clone())), HistoryProgress::Completed),
                            None => self.complete(Ok(HistoryView::new(view, None, self.clone())), HistoryProgress::Fault),
                        }
                    }
                    std::task::Poll::Ready(Ok(Err(error))) => {
                        work.take();
                        drop(work);
                        self.complete(Err(error), HistoryProgress::Fault);
                    }
                    std::task::Poll::Ready(Err(error)) => {
                        work.take();
                        drop(work);
                        self.complete(Err(error), HistoryProgress::Fault);
                    }
                }
            }
            None => {}
        }
    }

    fn close_one(self: &Arc<Self>) -> bool {
        if self.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take().is_some() {
            return true;
        }
        if self.retry_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take().is_some() {
            return true;
        }
        if let Some(work) = self.terminal_work.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take() {
            match work {
                ArtifactHistoryWorkOwner::Request => self.begin_unhanded_reservation_close(),
                ArtifactHistoryWorkOwner::Actor(owner) => {
                    *self.work.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(ArtifactHistoryWorkOwner::Actor(owner));
                    self.cancelled.store(true, std::sync::atomic::Ordering::Release);
                    self.schedule();
                }
            }
            return true;
        }
        let mut reservation = self.terminal_reservation.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if let Some(cursor) = reservation.as_mut() {
            if cursor.close_step() {
                return true;
            }
            if cursor.terminal_is_empty() {
                reservation.take();
                return true;
            }
        }
        drop(reservation);
        let mut construction = self.terminal_construction.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if let Some(cursor) = construction.as_mut() {
            if cursor.close_step() {
                return true;
            }
            if cursor.terminal_is_empty() {
                construction.take();
                return true;
            }
        }
        drop(construction);
        let mut terminal = self.terminal_result.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
        if let Some(result) = terminal.as_mut() {
            match result {
                Ok(view) => {
                    if view.close_step() {
                        return true;
                    }
                    terminal.take();
                    return true;
                }
                Err(_) => {
                    terminal.take();
                    return true;
                }
            }
        }
        false
    }
}

impl HistoryFuture {
    fn take_completion(&mut self) -> Option<ArtifactHistoryOutcome> {
        let result = self.state.completion.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
        if result.is_some() {
            self.state.waker.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
            self.resolved = true;
            self.state.finish_if_terminal_empty();
        }
        result
    }

    fn submit(handle: &ArtifactHandle) -> Self {
        let future = Self::prepare(handle);
        let ready = future.state.work.lock().unwrap_or_else(std::sync::PoisonError::into_inner).is_some();
        if ready {
            future.state.schedule();
        }
        future
    }

    fn prepare(handle: &ArtifactHandle) -> Self {
        let (admission, construction_fault, rejected_error, generation) = match ArtifactHistoryAdmission::try_claim() {
            Ok(admission) => {
                let generation = admission.generation;
                (Some(admission), None, None, generation)
            }
            Err(ArtifactHistoryAdmissionError::Construction { admission, fault }) => {
                let generation = admission.generation;
                (Some(admission), Some(fault), None, generation)
            }
            Err(ArtifactHistoryAdmissionError::Rejected(error)) => (None, None, Some(error), 0),
        };
        let ready = construction_fault.is_none() && rejected_error.is_none();
        let state = Arc::new(ArtifactHistoryState {
            pool: handle.pool.as_ref().clone(),
            authority: handle.authority.clone(),
            generation,
            authority_generation: handle.authority.generation(),
            admission: Mutex::new(admission),
            work: Mutex::new(ready.then_some(ArtifactHistoryWorkOwner::Request)),
            completion: Mutex::new(None),
            terminal_work: Mutex::new(None),
            terminal_result: Mutex::new(None),
            terminal_reservation: Mutex::new(None),
            reservation_checked_out: std::sync::atomic::AtomicBool::new(false),
            terminal_construction: Mutex::new(construction_fault),
            construction_checked_out: std::sync::atomic::AtomicBool::new(false),
            retry_job: Mutex::new(None),
            terminal_job: Mutex::new(None),
            waker: Mutex::new(None),
            retry_armed: std::sync::atomic::AtomicBool::new(false),
            retry_generation: std::sync::atomic::AtomicU64::new(1),
            scheduled: std::sync::atomic::AtomicBool::new(false),
            cancelled: Arc::new(std::sync::atomic::AtomicBool::new(false)),
            abandoned: std::sync::atomic::AtomicBool::new(false),
            finished: std::sync::atomic::AtomicBool::new(false),
            progress: std::sync::atomic::AtomicU8::new(if generation == 0 { HistoryProgress::Fault as u8 } else { HistoryProgress::Admitted as u8 }),
            #[cfg(test)]
            controlled_completion_hook: Mutex::new(None),
            #[cfg(test)]
            controlled_publication_before_waker_hook: Mutex::new(None),
        });
        register_artifact_history(&state);
        let construction_error = state.terminal_construction.lock().unwrap_or_else(std::sync::PoisonError::into_inner).as_mut().and_then(db_artifact::HistoryReplayReservationConstructionFault::take_error);
        if let Some(error) = rejected_error.or(construction_error) {
            *state.completion.lock().unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Err(error));
        }
        Self { state, resolved: false }
    }

    pub fn generation(&self) -> u64 {
        self.state.generation
    }

    pub fn terminal_handle(&self) -> ArtifactHistoryTerminalHandle {
        ArtifactHistoryTerminalHandle { state: self.state.clone() }
    }

    pub fn progress(&self) -> HistoryProgress {
        match self.state.progress.load(std::sync::atomic::Ordering::Acquire) {
            0 => HistoryProgress::Admitted,
            1 => HistoryProgress::Scheduled,
            2 => HistoryProgress::Waiting,
            3 => HistoryProgress::Mapping,
            4 => HistoryProgress::Completed,
            5 => HistoryProgress::Cancelled,
            _ => HistoryProgress::Fault,
        }
    }

    pub fn cancel(&self) {
        if !matches!(self.progress(), HistoryProgress::Completed | HistoryProgress::Cancelled | HistoryProgress::Fault) {
            self.state.cancelled.store(true, std::sync::atomic::Ordering::Release);
            if !self.state.terminalize_unhanded_request(Err(DbError::Closed), HistoryProgress::Cancelled) {
                self.state.schedule();
            }
        }
    }

    pub fn take_terminal_job(&self) -> Option<ArtifactHistoryTerminalJob> {
        self.state.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take().map(|owner| ArtifactHistoryTerminalJob { state: self.state.clone(), owner: Some(owner) })
    }

    pub fn take_terminal_work(&self) -> Option<ArtifactHistoryTerminalWork> {
        self.state.terminal_work.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take().map(|owner| ArtifactHistoryTerminalWork { state: self.state.clone(), owner: Some(owner) })
    }

    pub fn take_terminal_reservation(&self) -> Option<ArtifactHistoryTerminalReservation> {
        self.state.take_terminal_reservation()
    }

    pub fn take_terminal_construction_fault(&self) -> Option<ArtifactHistoryTerminalConstructionFault> {
        self.state.take_terminal_construction_fault()
    }

    pub fn take_terminal_result(&self) -> Option<ArtifactHistoryOutcome> {
        let mut result = self.state.terminal_result.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take();
        if let Some(Ok(view)) = result.as_mut() {
            view.rearm_terminal_return();
        }
        if result.is_some() {
            self.state.finish_if_terminal_empty();
        }
        result
    }

    pub fn take_actor_terminal_job(&self) -> Option<db_artifact::ArtifactRunnerTerminalJob> {
        self.state.authority.take_terminal_job()
    }

    pub fn close_step(&self) -> bool {
        if self.state.close_one() {
            return true;
        }
        if self.state.authority.close_step() {
            return true;
        }
        self.state.finish_if_terminal_empty()
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.state.terminal_is_empty() && self.state.authority.terminal_is_empty()
    }
}

impl ArtifactHistoryTerminalHandle {
    pub fn generation(&self) -> u64 {
        self.state.generation
    }

    pub fn take_terminal_job(&self) -> Option<ArtifactHistoryTerminalJob> {
        self.state.terminal_job.lock().unwrap_or_else(std::sync::PoisonError::into_inner).take().map(|owner| ArtifactHistoryTerminalJob { state: self.state.clone(), owner: Some(owner) })
