    Encode,
    Seal,
    Claim,
    Handoff,
    Poll,
    CloseWork,
    Revalidate,
    Retire,
    Publish,
    Terminal,
}

impl DatabaseCreateCatalogPhase {
    fn from_u8(value: u8) -> Self {
        match value {
            0 => Self::Scan,
            1 => Self::Reserve,
            2 => Self::Clone,
            3 => Self::Snapshot,
            4 => Self::Encode,
            5 => Self::Seal,
            6 => Self::Claim,
            7 => Self::Handoff,
            8 => Self::Poll,
            9 => Self::CloseWork,
            10 => Self::Revalidate,
            11 => Self::Retire,
            12 => Self::Publish,
            _ => Self::Terminal,
        }
    }
}

#[repr(u8)]
